    std::string FormatClassLocal(uint8_t classId)
    {
        switch (classId) {
            case CLASS_WARRIOR:      return "Warrior";
            case CLASS_PALADIN:      return "Paladin";
            case CLASS_HUNTER:       return "Hunter";
            case CLASS_ROGUE:        return "Rogue";
            case CLASS_PRIEST:       return "Priest";
            case CLASS_DEATH_KNIGHT: return "Death Knight";
            case CLASS_SHAMAN:       return "Shaman";
            case CLASS_MAGE:         return "Mage";
            case CLASS_WARLOCK:      return "Warlock";
            case CLASS_DRUID:        return "Druid";
            default:                 return "Unknown";
        }
    }

    std::string FormatRaceLocal(uint8_t raceId)
    {
        switch (raceId) {
            case RACE_HUMAN:         return "Human";
            case RACE_ORC:           return "Orc";
            case RACE_DWARF:         return "Dwarf";
            case RACE_NIGHTELF:      return "Night Elf";
            case RACE_UNDEAD_PLAYER: return "Undead";
            case RACE_TAUREN:        return "Tauren";
            case RACE_GNOME:         return "Gnome";
            case RACE_TROLL:         return "Troll";
            case RACE_BLOODELF:      return "Blood Elf";
            case RACE_DRAENEI:       return "Draenei";
            default:                 return "Unknown";
        }
    }

    nlohmann::json DescribePlayer(Player* p)
    {
        if (!p) return nlohmann::json{{"error", "player not found"}};
        nlohmann::json j;
        j["name"]   = p->GetName();
        j["level"]  = p->GetLevel();
        j["class"]  = FormatClassLocal(p->getClass());
        j["race"]   = FormatRaceLocal(p->getRace());
        j["health_pct"] = p->GetHealthPct();
        if (p->IsInWorld())
        {
            uint32 zoneId = p->GetZoneId();
            uint32 areaId = p->GetAreaId();
            if (auto const* z = sAreaTableStore.LookupEntry(zoneId))
                j["zone"] = z->area_name[LocaleConstant::LOCALE_enUS];
            if (auto const* a = sAreaTableStore.LookupEntry(areaId))
                j["area"] = a->area_name[LocaleConstant::LOCALE_enUS];
        }
        return j;
    }

    // --- Tool implementations ---

    nlohmann::json Tool_GetBotState(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        if (botGuid == 0)
            return nlohmann::json{{"error", "missing required argument 'botGuid' (numeric); see system prompt for the active value"}};
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        return DescribePlayer(bot);
    }

    nlohmann::json Tool_GetPlayerState(uint64_t /*botGuid*/, uint64_t playerGuid, const nlohmann::json& args)
    {
        std::string name = args.value("name", std::string{});
        if (name.empty() && playerGuid == 0)
            return nlohmann::json{{"error", "missing required argument: pass 'playerGuid' (numeric) or 'name' (string)"}};
        Player* target = nullptr;
        if (name.empty())
            target = ObjectAccessor::FindPlayer(ObjectGuid(playerGuid));
        else
            target = ObjectAccessor::FindPlayerByName(name);
        return DescribePlayer(target);
    }

    nlohmann::json Tool_GetZoneInfo(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        if (botGuid == 0)
            return nlohmann::json{{"error", "missing required argument 'botGuid' (numeric); see system prompt for the active value"}};
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot || !bot->IsInWorld()) return nlohmann::json{{"error", "bot not in world"}};
        nlohmann::json j;
        uint32 zoneId = bot->GetZoneId();
        uint32 areaId = bot->GetAreaId();
        j["zone_id"] = zoneId;
        j["area_id"] = areaId;
        if (auto const* z = sAreaTableStore.LookupEntry(zoneId))
            j["zone_name"] = z->area_name[LocaleConstant::LOCALE_enUS];
        if (auto const* a = sAreaTableStore.LookupEntry(areaId))
            j["area_name"] = a->area_name[LocaleConstant::LOCALE_enUS];
        j["map_id"] = bot->GetMapId();
        j["x"] = bot->GetPositionX();
        j["y"] = bot->GetPositionY();
        j["z"] = bot->GetPositionZ();
        return j;
    }

    nlohmann::json Tool_WhisperPlayer(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (botGuid == 0)
            return nlohmann::json{{"error", "missing required argument 'botGuid' (numeric)"}};
        std::string targetName = args.value("name", std::string{});
        std::string message    = args.value("message", std::string{});
        if (targetName.empty() || message.empty())
            return nlohmann::json{{"error", "name and message are required"}};

        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found"}};

        Player* target = ObjectAccessor::FindPlayerByName(targetName);
        if (!target) return nlohmann::json{{"error", "target player offline"}};

        PlayerbotAI* ai = PlayerbotsMgr::instance().GetPlayerbotAI(bot);
        if (!ai) return nlohmann::json{{"error", "bot has no PlayerbotAI"}};

        // Cap length to one whisper to avoid abuse.
        if (message.size() > 200) message.resize(200);
        ai->Whisper(message, target->GetName());
        return nlohmann::json{{"ok", true}, {"sent_to", targetName}};
    }

    // ------------------------------------------------------------------
    // talk_to_leader — voice / external chat-injection seam.
    //
    // Feeds a synthetic player message to the leader bot's gateway brain
    // EXACTLY as an in-game whisper would, runs the full gateway tool-loop
    // (Claude calls game MCP tools to drive the squad), and returns Claude's
    // in-character reply. This lets a hands-free voice client (mic -> STT ->
    // POST) command AND converse with the leader without the human typing in
    // the WoW client — the seam the chat hook (OnPlayerCanUseChat) never
    // exposed to external callers.
    //
    // Threading: runs on the MCP server's httplib worker thread, which is
    // already OFF the world thread — the same off-thread context the in-game
    // whisper path uses (mod-ollama-chat_handler.cpp spawns a detached
    // std::thread before calling QueryGatewayAPIWithTools). DispatchGatewayTool
    // re-resolves Player*/bot pointers on every tool call, so the established
    // pointer-revalidation contract holds here unchanged. The call blocks this
    // worker thread until the gateway round-trip + tool loop finishes; the Mac
    // client waits for the HTTP response. Gated by Mcp.AllowGatewayInjection.
    // ------------------------------------------------------------------
    nlohmann::json Tool_TalkToLeader(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!g_McpAllowGatewayInjection)
            return nlohmann::json{{"error", "gateway injection disabled (set OllamaChat.Mcp.AllowGatewayInjection = 1)"}};

        // botGuid arrives already defaulted to the configured single leader by
        // ExtractIdentity; an explicit botGuid arg still overrides.
        if (args.contains("botGuid") && args["botGuid"].is_number())
            botGuid = args["botGuid"].get<uint64_t>();
        if (botGuid == 0)
            return nlohmann::json{{"error", "no leader bot resolved (pass 'botGuid' or configure a single OllamaChat.Mcp.Leader.BotGUIDs)"}};

        std::string message = args.value("message", std::string{});
        if (message.empty())
            return nlohmann::json{{"error", "missing required argument 'message'"}};

        // Resolve the speaking player. Their identity matters: the gateway
        // system prompt addresses them, leader_command routes through their
        // master session (AutoClaim), and the reply whispers back to them.
        if (args.contains("playerGuid") && args["playerGuid"].is_number())
            playerGuid = args["playerGuid"].get<uint64_t>();
        std::string playerName = args.value("playerName", std::string{});
        if (playerGuid == 0 && !playerName.empty())
        {
            Player* p = ObjectAccessor::FindPlayerByName(playerName);
            if (!p) return nlohmann::json{{"error", "player not found / offline: " + playerName}};
            playerGuid = p->GetGUID().GetCounter();
        }
        if (playerGuid == 0)
            return nlohmann::json{{"error", "missing player identity: provide 'playerName' (online) or 'playerGuid'"}};

        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot || !bot->IsInWorld())
            return nlohmann::json{{"error", "leader bot not in world"}};

        // Synthiq honors request-body tools[] (so the in-game tool loop fires);
        // OpenClaw ignores tools[] but runs its own MCP toolset, so the plain
        // query still lets it act + reply. Mirror the chat handler's branch.
        std::string gatewayType = ResolveGatewayType(botGuid);
        bool useTools = g_GatewayEnableToolUse && gatewayType == "synthiq";

        auto t0 = std::chrono::steady_clock::now();
        std::string reply = useTools
            ? QueryGatewayAPIWithTools(botGuid, playerGuid, message)
            : QueryGatewayAPI(botGuid, playerGuid, message);
        auto latencyMs = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - t0).count();

        if (reply.empty())
            return nlohmann::json{{"error", "gateway returned empty response"},
                                  {"latency_ms", static_cast<uint64_t>(latencyMs)}};

        // Preserve conversation continuity so follow-up voice commands have
        // context (QueryGatewayAPI* reads this same store on the next call).
        AppendBotConversation(botGuid, playerGuid, message, reply);

        // Optionally also emit the reply in-game so it shows in the player's WoW
        // chat log (default off — the reply is returned in the tool result and a
        // voice client typically speaks it via TTS; in-game echo is opt-in to
        // avoid duplicate text). Re-resolve pointers (we may have round-tripped
        // several seconds) before touching game objects.
        bool whispered = false;
        if (args.value("emit_in_game", false))
        {
            Player* botPtr    = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
            Player* playerPtr = ObjectAccessor::FindPlayer(ObjectGuid(playerGuid));
            if (botPtr && playerPtr)
            {
                if (PlayerbotAI* ai = PlayerbotsMgr::instance().GetPlayerbotAI(botPtr))
                {
                    for (const std::string& chunk : SplitForWhisper(reply, g_GatewayMaxWhisperChunkChars))
                        ai->Whisper(chunk, playerPtr->GetName());
                    whispered = true;
                }
            }
        }

        return nlohmann::json{
            {"ok",                true},
            {"reply",             reply},
            {"bot_guid",          botGuid},
            {"player_guid",       playerGuid},
            {"gateway_type",      gatewayType},
            {"used_tools",        useTools},
            {"whispered_in_game", whispered},
            {"latency_ms",        static_cast<uint64_t>(latencyMs)}
        };
    }

    // ------------------------------------------------------------------
    // Tactical directive tools — the paid gateway's response to a
    // tactical escalation is expected to call tactical_set_directive,
    // which writes a goal string + TTL that the local tactical loop
    // reads on its next tick. tactical_get_directive lets any tool-use
    // client (or a human operator) inspect the current directive.
    // ------------------------------------------------------------------
    nlohmann::json Tool_TacticalGetDirective(uint64_t /*botGuid*/, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        uint64_t target = 0;
        if (args.contains("bot_guid")) target = args.value("bot_guid", uint64_t{0});
        else if (args.contains("botGuid")) target = args.value("botGuid", uint64_t{0});
        if (target == 0)
            return nlohmann::json{{"error", "missing required argument 'bot_guid' (numeric)"}};

        TacticalDirective d = GetTacticalDirective(target);
        if (!d.IsActive(time(nullptr)))
            return nlohmann::json{{"bot_guid", target}, {"active", false}};

        return nlohmann::json{
            {"bot_guid",   target},
            {"active",     true},
            {"goal",       d.goal},
            {"set_at",     static_cast<uint64_t>(d.setAt)},
            {"expires_at", static_cast<uint64_t>(d.expiresAt)},
            {"set_by",     d.setBy},
        };
    }

    nlohmann::json Tool_TacticalSetDirective(uint64_t /*botGuid*/, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!g_McpAllowActionTools)
            return nlohmann::json{{"error", "action tools disabled (Mcp.AllowActionTools=0)"}};

        uint64_t target = 0;
        if (args.contains("bot_guid")) target = args.value("bot_guid", uint64_t{0});
        else if (args.contains("botGuid")) target = args.value("botGuid", uint64_t{0});
        if (target == 0)
            return nlohmann::json{{"error", "missing required argument 'bot_guid' (numeric)"}};

        std::string goal = args.value("goal", std::string{});
        uint32_t    ttl  = args.value("ttl_sec", uint32_t{300});

        // Defense: only accept if target bot is in the tactical allowlist —
        // this tool should never set directives for non-tactical bots.
        if (!goal.empty() && g_TacticalBotGUIDSet.count(target) == 0)
            return nlohmann::json{{"error", "target bot not in Tactical.BotGUIDs"}, {"bot_guid", target}};

        // Directive arbitration — operator intent wins over escalation.
        // Three sources, distinguished at the dispatch boundary:
        //   "escalation"    — the strategic worker's in-process gateway call
        //                     (thread-local flag set around it in tactical.cpp)
        //   "player:<guid>" — a voice-fallback path (talk_to_leader carries the
        //                     speaking player's guid through the tool loop)
        //   "mcp"           — the operator's external agent over the HTTP MCP
        //                     (the bridge strips undeclared args → playerGuid=0)
        std::string setBy = InEscalationContext()
                            ? std::string("escalation")
                            : (playerGuid != 0 ? fmt::format("player:{}", playerGuid)
                                               : std::string("mcp"));

        // An escalation may not overwrite (or clear) an ACTIVE directive set by
        // the operator or a player — their intent outranks the local model's
        // call for help. Expired operator directives don't block (IsActive()).
        // mcp/player writes always win and replace anything.
        if (setBy == "escalation")
        {
            TacticalDirective existing = GetTacticalDirective(target);
            if (existing.IsActive(time(nullptr)) && existing.setBy != "escalation")
            {
                return nlohmann::json{
                    {"ok",          false},
                    {"reason",      "superseded_by_operator_directive"},
                    {"bot_guid",    target},
                    {"active_goal", existing.goal},
                    {"set_by",      existing.setBy},
                    {"expires_at",  static_cast<uint64_t>(existing.expiresAt)},
                    {"hint",        "an operator/player directive is active for this bot; work toward it or wait for it to expire"}
                };
            }
        }

        SetTacticalDirective(target, goal, ttl, setBy);
        return nlohmann::json{
            {"ok",        true},
            {"bot_guid",  target},
            {"goal",      goal},
            {"ttl_sec",   static_cast<uint64_t>(std::min<uint32_t>(ttl, g_TacticalDirectiveMaxTtlSec))},
            {"cleared",   goal.empty()},
        };
    }

    // --- PR8b read-only tools ---

    // Resolve a player either by 'name' arg (if provided), else fall back to the
    // playerGuid passed by the MCP transport (the whisperer).
    Player* ResolveTargetPlayer(uint64_t playerGuid, const nlohmann::json& args)
    {
        std::string name = args.value("name", std::string{});
        if (!name.empty())
            return ObjectAccessor::FindPlayerByName(name);
        if (playerGuid != 0)
            return ObjectAccessor::FindPlayer(ObjectGuid(playerGuid));
        return nullptr;
    }

    // Helper: render one Item* as a compact JSON object.
    nlohmann::json DescribeItem(Item* it)
    {
        nlohmann::json j;
        if (!it) return j;
        ItemTemplate const* t = it->GetTemplate();
        j["item_id"] = it->GetEntry();
        if (t)
        {
            j["name"]    = t->Name1;
            j["item_lvl"] = t->ItemLevel;
            j["quality"]  = t->Quality;
            j["required_level"] = t->RequiredLevel;
        }
        if (it->GetCount() > 1) j["count"] = it->GetCount();
        // Enchantments — only check the permanent slot to keep payload small.
        if (uint32 ench = it->GetEnchantmentId(PERM_ENCHANTMENT_SLOT))
            j["perm_enchant_id"] = ench;
        return j;
    }

    nlohmann::json Tool_GetPlayerGear(uint64_t /*botGuid*/, uint64_t playerGuid, const nlohmann::json& args)
    {
        Player* p = ResolveTargetPlayer(playerGuid, args);
        if (!p) return nlohmann::json{{"error", "player not found"}};

        nlohmann::json slots = nlohmann::json::object();
        // Iterate the 19 visible equipment slots (head through tabard).
        for (uint8 slot = EQUIPMENT_SLOT_START; slot < EQUIPMENT_SLOT_END; ++slot)
        {
            Item* it = p->GetItemByPos(INVENTORY_SLOT_BAG_0, slot);
            if (!it) continue;
            slots[std::to_string(slot)] = DescribeItem(it);
        }

        // Aggregate average iLvl across equipped pieces (a useful one-glance metric).
        uint32 sum = 0, n = 0;
        for (uint8 slot = EQUIPMENT_SLOT_START; slot < EQUIPMENT_SLOT_END; ++slot)
        {
            Item* it = p->GetItemByPos(INVENTORY_SLOT_BAG_0, slot);
            if (!it || !it->GetTemplate()) continue;
            sum += it->GetTemplate()->ItemLevel;
            ++n;
        }

        nlohmann::json out;
        out["name"]   = p->GetName();
        out["slots"]  = std::move(slots);
        out["equipped_pieces"] = n;
        if (n > 0) out["avg_item_level"] = sum / n;
        return out;
    }

    nlohmann::json Tool_GetPlayerQuests(uint64_t /*botGuid*/, uint64_t playerGuid, const nlohmann::json& args)
    {
        Player* p = ResolveTargetPlayer(playerGuid, args);
        if (!p) return nlohmann::json{{"error", "player not found"}};

        nlohmann::json quests = nlohmann::json::array();
        for (auto const& [questId, statusData] : p->getQuestStatusMap())
        {
            // Only INCOMPLETE / COMPLETE entries are interesting for "what should I do next?".
            if (statusData.Status != QUEST_STATUS_INCOMPLETE && statusData.Status != QUEST_STATUS_COMPLETE)
                continue;
            Quest const* q = sObjectMgr->GetQuestTemplate(questId);
            if (!q) continue;

            nlohmann::json qj;
            qj["id"]    = questId;
            qj["title"] = q->GetTitle();
            qj["level"] = q->GetQuestLevel();
            qj["status"] = (statusData.Status == QUEST_STATUS_COMPLETE) ? "complete" : "incomplete";
            if (uint32 zone = q->GetZoneOrSort()) qj["zone_or_sort"] = zone;
            quests.push_back(qj);
        }
        return nlohmann::json{
            {"name", p->GetName()},
            {"quest_count", quests.size()},
            {"quests", std::move(quests)}
        };
    }

    // Bot-side mirror of get_player_quests: the BOT's own active quest log, with an inline
    // objectives_summary so the agent can prioritise without an N× get_quest_details fan-out
    // for every entry. Sorted ready-to-turn-in first, then by quest level desc.
    //
    // Closes the autonomous-questing loop: get_nearby_creatures (find quest-givers) →
    // bot_accept_quest → get_bot_quests (what's on my log? what's done?) → get_quest_details
    // (drill-down on a specific quest) → bot_turn_in_quest. Without this the agent can take
    // quests but is blind to "what do I already have / what's ready to hand in", which makes
    // it either re-query NPCs every tick or fabricate confident-but-wrong status answers.
    nlohmann::json Tool_GetBotQuests(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        if (botGuid == 0)
            return nlohmann::json{{"error", "missing required argument 'botGuid' (numeric)"}};
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};

        nlohmann::json quests = nlohmann::json::array();
        uint32 readyCount = 0;
        uint32 incompleteCount = 0;

        for (auto const& [questId, statusData] : bot->getQuestStatusMap())
        {
            // Mirrors get_player_quests — only active log entries are interesting.
            // QUEST_STATUS_REWARDED = already turned in; QUEST_STATUS_NONE = stale row.
            if (statusData.Status != QUEST_STATUS_INCOMPLETE && statusData.Status != QUEST_STATUS_COMPLETE)
                continue;
            Quest const* q = sObjectMgr->GetQuestTemplate(questId);
            if (!q) continue;

            bool ready = (statusData.Status == QUEST_STATUS_COMPLETE);
            if (ready) ++readyCount;
            else       ++incompleteCount;

            nlohmann::json qj;
            qj["id"]               = questId;
            qj["title"]            = q->GetTitle();
            qj["level"]            = q->GetQuestLevel();
            qj["status"]           = ready ? "complete" : "incomplete";
            qj["ready_to_turn_in"] = ready;
            if (uint32 zone = q->GetZoneOrSort()) qj["zone_or_sort"] = zone;

            // Inline summary: "5/10 Mangy Wolf | 0/5 Wolf Pelt". Empty for talk-to-NPC
            // quests with no kill/collect objectives. Lets the agent skim the log and
            // pick the most-progressed quest to push without an extra round-trip per quest.
            std::string summary;
            auto append = [&summary](const std::string& part) {
                if (!summary.empty()) summary += " | ";
                summary += part;
            };
            for (uint32 i = 0; i < QUEST_OBJECTIVES_COUNT; ++i)
            {
                int32 ent = q->RequiredNpcOrGo[i];
                uint32 need = q->RequiredNpcOrGoCount[i];
                if (ent == 0 && need == 0) continue;
                uint16 cur = statusData.CreatureOrGOCount[i];
                std::string name;
                if (ent > 0)
                {
                    if (CreatureTemplate const* ct = sObjectMgr->GetCreatureTemplate(static_cast<uint32>(ent)))
                        name = ct->Name;
                }
                else
                {
                    if (GameObjectTemplate const* gt = sObjectMgr->GetGameObjectTemplate(static_cast<uint32>(-ent)))
                        name = gt->name;
                }
                if (name.empty()) name = "target";
                append(fmt::format("{}/{} {}", cur, need, name));
            }
            for (uint32 i = 0; i < QUEST_ITEM_OBJECTIVES_COUNT; ++i)
            {
                uint32 id = q->RequiredItemId[i];
                uint32 need = q->RequiredItemCount[i];
                if (id == 0 && need == 0) continue;
                uint16 cur = statusData.ItemCount[i];
                std::string name;
                if (ItemTemplate const* it = sObjectMgr->GetItemTemplate(id))
                    name = it->Name1;
                if (name.empty()) name = "item";
                append(fmt::format("{}/{} {}", cur, need, name));
            }
            if (!summary.empty())
                qj["objectives_summary"] = std::move(summary);

            quests.push_back(std::move(qj));
        }

        // Surface ready-to-turn-in entries first (most actionable), then by quest level desc.
        // Equal-level ties keep insertion order (stable sort would be cleaner but std::sort
        // on a small log is fine here — quest log caps at 25).
        std::sort(quests.begin(), quests.end(), [](nlohmann::json const& a, nlohmann::json const& b) {
            bool ar = a.value("ready_to_turn_in", false);
            bool br = b.value("ready_to_turn_in", false);
            if (ar != br) return ar;
            return a.value("level", 0) > b.value("level", 0);
        });

        return nlohmann::json{
            {"name",             bot->GetName()},
            {"level",            bot->GetLevel()},
            {"quest_count",      quests.size()},
            {"ready_to_turn_in", readyCount},
            {"incomplete",       incompleteCount},
            {"quests",           std::move(quests)}
        };
    }

    // Drill-down from get_player_quests: given a quest_id, return everything the agent
    // needs to actually work the quest — objectives + current progress, rewards (incl.
    // choice items), turn-in readiness. Without this, a bot that has a quest on its log
    // is blind to "what do I still need to kill / collect / where do I turn it in".
    // Pairs with get_nearby_creatures (find quest-givers / mobs) and bot_turn_in_quest.
    nlohmann::json Tool_GetQuestDetails(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!args.contains("quest_id") || !args["quest_id"].is_number())
            return nlohmann::json{{"error", "missing numeric 'quest_id'"}};
        uint32 questId = args["quest_id"].get<uint32>();

        Quest const* q = sObjectMgr->GetQuestTemplate(questId);
        if (!q) return nlohmann::json{{"error", "quest not found"}, {"quest_id", questId}};

        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};

        nlohmann::json out;
        out["id"]       = questId;
        out["title"]    = q->GetTitle();
        out["level"]    = q->GetQuestLevel();
        out["min_level"] = q->GetMinLevel();
        if (int32 zone = q->GetZoneOrSort()) out["zone_or_sort"] = zone;
        std::string const& objText = q->GetObjectives();
        if (!objText.empty()) out["objectives_text"] = objText;

        // Merge the bot's personal quest-status row (if on log) with the static template.
        // Absent from the status map ⇒ bot has never taken this quest; report status:"none".
        auto const& statusMap = bot->getQuestStatusMap();
        auto sit = statusMap.find(questId);
        bool onLog = (sit != statusMap.end() && sit->second.Status != QUEST_STATUS_NONE);
        out["on_quest_log"] = onLog;

        auto statusToString = [](QuestStatus s) -> const char* {
            switch (s)
            {
                case QUEST_STATUS_COMPLETE:   return "complete";
                case QUEST_STATUS_INCOMPLETE: return "incomplete";
                case QUEST_STATUS_FAILED:     return "failed";
                case QUEST_STATUS_REWARDED:   return "rewarded";
                default:                      return "none";
            }
        };
        QuestStatus status = onLog ? sit->second.Status : QUEST_STATUS_NONE;
        out["status"] = statusToString(status);
        // A quest with status==COMPLETE is "ready to turn in" — the core's objective
        // tracker has already flagged all requirements as met. Surface this as a clear
        // boolean so the agent doesn't have to interpret the enum.
        out["ready_to_turn_in"] = (status == QUEST_STATUS_COMPLETE);

        // --- Creature / GameObject kill objectives (up to QUEST_OBJECTIVES_COUNT=4 slots) ---
        // RequiredNpcOrGo[]: >0 = creature entry, <0 = gameobject entry (signed sentinel).
        // Zero-valued slots are unused — skip.
        nlohmann::json creatureObjs = nlohmann::json::array();
        bool allKillsMet = true;
        for (uint32 i = 0; i < QUEST_OBJECTIVES_COUNT; ++i)
        {
            int32 ent = q->RequiredNpcOrGo[i];
            uint32 need = q->RequiredNpcOrGoCount[i];
            if (ent == 0 && need == 0) continue;

            uint16 cur = onLog ? sit->second.CreatureOrGOCount[i] : static_cast<uint16>(0);
            bool done = (cur >= need);
            if (!done) allKillsMet = false;

            uint32 resolvedId = (ent >= 0) ? static_cast<uint32>(ent) : static_cast<uint32>(-ent);
            nlohmann::json slot;
            slot["slot"]           = i;
            slot["required_id"]    = resolvedId;
            slot["required_type"]  = (ent >= 0) ? "creature" : "gameobject";
            slot["required_count"] = need;
            slot["current_count"]  = cur;
            slot["complete"]       = done;
            // Resolve name via template store (world DB, cached in memory).
            if (ent > 0)
            {
                if (CreatureTemplate const* ct = sObjectMgr->GetCreatureTemplate(resolvedId))
                    slot["required_name"] = ct->Name;
            }
            else if (ent < 0)
            {
                if (GameObjectTemplate const* gt = sObjectMgr->GetGameObjectTemplate(resolvedId))
                    slot["required_name"] = gt->name;
            }
            if (!q->ObjectiveText[i].empty()) slot["text"] = q->ObjectiveText[i];
            creatureObjs.push_back(std::move(slot));
        }
        out["creature_objectives"] = std::move(creatureObjs);

        // --- Item collection objectives (up to QUEST_ITEM_OBJECTIVES_COUNT=6 slots) ---
        nlohmann::json itemObjs = nlohmann::json::array();
        bool allItemsMet = true;
        for (uint32 i = 0; i < QUEST_ITEM_OBJECTIVES_COUNT; ++i)
        {
            uint32 id = q->RequiredItemId[i];
            uint32 need = q->RequiredItemCount[i];
            if (id == 0 && need == 0) continue;

            uint16 cur = onLog ? sit->second.ItemCount[i] : static_cast<uint16>(0);
            bool done = (cur >= need);
            if (!done) allItemsMet = false;

            nlohmann::json slot;
            slot["slot"]           = i;
            slot["item_id"]        = id;
            slot["required_count"] = need;
            slot["current_count"]  = cur;
            slot["complete"]       = done;
            if (ItemTemplate const* it = sObjectMgr->GetItemTemplate(id))
                slot["item_name"] = it->Name1;
            itemObjs.push_back(std::move(slot));
        }
        out["item_objectives"] = std::move(itemObjs);
        out["all_objectives_met"] = (allKillsMet && allItemsMet);

        // --- Rewards ---
        // GetRewOrReqMoney: negative = turn-in costs money (rare, e.g. some reputation
        // quests); positive = money reward. We report both as separate fields so the
        // agent doesn't have to reinterpret a signed value.
        nlohmann::json rewards;
        int32 money = q->GetRewOrReqMoney(bot->GetLevel());
        if (money >= 0) rewards["money_copper"] = money;
        else            rewards["money_cost_copper"] = -money;

        // XPValue is level-scaled; pass the bot's own level so the result reflects what
        // this bot would actually earn.
        rewards["xp"]        = q->XPValue(bot->GetLevel());
        rewards["honor"]     = q->CalculateHonorGain(bot->GetLevel());
        if (uint32 spellId = q->GetRewSpellCast()) rewards["spell_cast_id"] = spellId;

        nlohmann::json autoItems = nlohmann::json::array();
        for (uint32 i = 0; i < QUEST_REWARDS_COUNT; ++i)
        {
            uint32 id = q->RewardItemId[i];
            uint32 cnt = q->RewardItemIdCount[i];
            if (id == 0) continue;
            nlohmann::json r{{"item_id", id}, {"count", cnt ? cnt : 1}};
            if (ItemTemplate const* it = sObjectMgr->GetItemTemplate(id))
                r["name"] = it->Name1;
            autoItems.push_back(std::move(r));
        }
        rewards["items_auto"] = std::move(autoItems);

        nlohmann::json choiceItems = nlohmann::json::array();
        for (uint32 i = 0; i < QUEST_REWARD_CHOICES_COUNT; ++i)
        {
            uint32 id = q->RewardChoiceItemId[i];
            uint32 cnt = q->RewardChoiceItemCount[i];
            if (id == 0) continue;
            nlohmann::json r{{"item_id", id}, {"count", cnt ? cnt : 1}};
            if (ItemTemplate const* it = sObjectMgr->GetItemTemplate(id))
                r["name"] = it->Name1;
            choiceItems.push_back(std::move(r));
        }
        rewards["items_choice"] = std::move(choiceItems);

        out["rewards"] = std::move(rewards);

        // --- Chain / prerequisite links ---
        // PrevQuestId: positive = parent quest in the same chain (optional breadcrumb);
        //              negative = absolute prerequisite (the agent must finish |prev|
        //              before this one will satisfy). We surface `strict_prereq` so the
        //              agent doesn't have to interpret the sign bit.
        // NextQuestId: the next quest in the chain (same author-intended path).
        // NextQuestInChain: RewardNextQuest — auto-offered by the same NPC on turn-in.
        // BreadcrumbForQuestId: this quest leads the player toward another quest hub.
        // ExclusiveGroup != 0: quest belongs to a mutually-exclusive set — picking one
        //                      locks out the others sharing the group. Lets the agent
        //                      avoid burning turn-ins on the wrong branch.
        nlohmann::json chain = nlohmann::json::object();
        auto linkWithTitle = [](uint32 id) -> nlohmann::json {
            nlohmann::json link{{"id", id}};
            if (Quest const* qt = sObjectMgr->GetQuestTemplate(id))
                link["title"] = qt->GetTitle();
            return link;
        };
        if (int32 prev = q->GetPrevQuestId())
        {
            bool strict = (prev < 0);
            uint32 pid = strict ? static_cast<uint32>(-prev) : static_cast<uint32>(prev);
            nlohmann::json link = linkWithTitle(pid);
            link["strict_prereq"] = strict;
            chain["prev"] = std::move(link);
        }
        if (uint32 next = q->GetNextQuestId())
            chain["next"] = linkWithTitle(next);
        if (uint32 chainNext = q->GetNextQuestInChain())
            chain["auto_offered_on_turnin"] = linkWithTitle(chainNext);
        if (uint32 breadcrumb = q->GetBreadcrumbForQuestId())
            chain["leads_to"] = linkWithTitle(breadcrumb);
        if (int32 excl = q->GetExclusiveGroup())
            chain["exclusive_group"] = excl;
        if (!chain.empty())
            out["chain"] = std::move(chain);

        return out;
    }

    // Per-objective progress for every active quest on the bot's log, returned in a single
    // call. get_bot_quests gives a compact summary string ("5/10 Mangy Wolf | 0/5 Wolf Pelt")
    // good for skimming, but the agent still has to fan out to get_quest_details once per
    // quest to read structured per-objective state (required_id, current_count, complete flag,
    // creature-vs-gameobject type, zone hints). With a typical 15-25 quest log that's
    // 15-25 round-trips just to answer "which objective in my zone is closest to done".
    //
    // This tool batches it: for each active quest entry, emit the same structured
    // creature_objectives[] + item_objectives[] arrays Tool_GetQuestDetails returns, plus
    // the quest header (title, level, zone_or_sort, status, ready_to_turn_in). Pure read,
    // no rewards / chain links — those are still a per-quest concern handled by
    // get_quest_details. Sorted ready-to-turn-in first, then by quest level desc, same as
    // get_bot_quests so the two tools stay aligned for the agent.
    nlohmann::json Tool_GetBotQuestLogExtended(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        if (botGuid == 0)
            return nlohmann::json{{"error", "missing required argument 'botGuid' (numeric)"}};
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};

        nlohmann::json quests = nlohmann::json::array();
        uint32 readyCount = 0;
        uint32 incompleteCount = 0;

        for (auto const& [questId, statusData] : bot->getQuestStatusMap())
        {
            // Active log entries only — rewarded/none rows are stale.
            if (statusData.Status != QUEST_STATUS_INCOMPLETE && statusData.Status != QUEST_STATUS_COMPLETE)
                continue;
            Quest const* q = sObjectMgr->GetQuestTemplate(questId);
            if (!q) continue;

            bool ready = (statusData.Status == QUEST_STATUS_COMPLETE);
            if (ready) ++readyCount;
            else       ++incompleteCount;

            nlohmann::json qj;
            qj["id"]               = questId;
            qj["title"]            = q->GetTitle();
            qj["level"]            = q->GetQuestLevel();
            qj["status"]           = ready ? "complete" : "incomplete";
            qj["ready_to_turn_in"] = ready;
            if (uint32 zone = q->GetZoneOrSort()) qj["zone_or_sort"] = zone;
            std::string const& objText = q->GetObjectives();
            if (!objText.empty()) qj["objectives_text"] = objText;

            // Creature / GameObject kill objectives — mirrors Tool_GetQuestDetails so the
            // shape is identical for downstream consumers.
            nlohmann::json creatureObjs = nlohmann::json::array();
            bool allKillsMet = true;
            for (uint32 i = 0; i < QUEST_OBJECTIVES_COUNT; ++i)
            {
                int32 ent = q->RequiredNpcOrGo[i];
                uint32 need = q->RequiredNpcOrGoCount[i];
                if (ent == 0 && need == 0) continue;

                uint16 cur = statusData.CreatureOrGOCount[i];
                bool done = (cur >= need);
                if (!done) allKillsMet = false;

                uint32 resolvedId = (ent >= 0) ? static_cast<uint32>(ent) : static_cast<uint32>(-ent);
                nlohmann::json slot;
                slot["slot"]           = i;
                slot["required_id"]    = resolvedId;
                slot["required_type"]  = (ent >= 0) ? "creature" : "gameobject";
                slot["required_count"] = need;
                slot["current_count"]  = cur;
                slot["complete"]       = done;
                if (ent > 0)
                {
                    if (CreatureTemplate const* ct = sObjectMgr->GetCreatureTemplate(resolvedId))
                        slot["required_name"] = ct->Name;
                }
                else if (ent < 0)
                {
                    if (GameObjectTemplate const* gt = sObjectMgr->GetGameObjectTemplate(resolvedId))
                        slot["required_name"] = gt->name;
                }
                if (!q->ObjectiveText[i].empty()) slot["text"] = q->ObjectiveText[i];
                creatureObjs.push_back(std::move(slot));
            }
            qj["creature_objectives"] = std::move(creatureObjs);

            nlohmann::json itemObjs = nlohmann::json::array();
            bool allItemsMet = true;
            for (uint32 i = 0; i < QUEST_ITEM_OBJECTIVES_COUNT; ++i)
            {
                uint32 id = q->RequiredItemId[i];
                uint32 need = q->RequiredItemCount[i];
                if (id == 0 && need == 0) continue;

                uint16 cur = statusData.ItemCount[i];
                bool done = (cur >= need);
                if (!done) allItemsMet = false;

                nlohmann::json slot;
                slot["slot"]           = i;
                slot["item_id"]        = id;
                slot["required_count"] = need;
                slot["current_count"]  = cur;
                slot["complete"]       = done;
                if (ItemTemplate const* it = sObjectMgr->GetItemTemplate(id))
                    slot["item_name"] = it->Name1;
                itemObjs.push_back(std::move(slot));
            }
            qj["item_objectives"] = std::move(itemObjs);
            qj["all_objectives_met"] = (allKillsMet && allItemsMet);

            quests.push_back(std::move(qj));
        }

        // Same ordering as get_bot_quests: ready-to-turn-in first (most actionable),
        // then by quest level desc.
        std::sort(quests.begin(), quests.end(), [](nlohmann::json const& a, nlohmann::json const& b) {
            bool ar = a.value("ready_to_turn_in", false);
            bool br = b.value("ready_to_turn_in", false);
            if (ar != br) return ar;
            return a.value("level", 0) > b.value("level", 0);
        });

        return nlohmann::json{
            {"name",             bot->GetName()},
            {"level",            bot->GetLevel()},
            {"quest_count",      quests.size()},
            {"ready_to_turn_in", readyCount},
            {"incomplete",       incompleteCount},
            {"quests",           std::move(quests)}
        };
    }

    // Drill-down for a single item: static template data (ilvl, stats, armor, damage,
    // requirements) merged with the bot's live state (can_use pass/fail, how many the
    // bot already owns, and what's currently in the equip slot(s) this item would
    // compete with so the agent can make pick-reward / loot decisions without a
    // second call).
    //
    // Pairs with get_quest_details' reward.items_choice, with loot drops, and with
    // vendor/AH browsing. Read-only, no side-effects.
    nlohmann::json Tool_GetItemDetails(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!args.contains("item_id") || !args["item_id"].is_number())
            return nlohmann::json{{"error", "missing numeric 'item_id'"}};
        uint32 itemId = args["item_id"].get<uint32>();

        ItemTemplate const* proto = sObjectMgr->GetItemTemplate(itemId);
        if (!proto) return nlohmann::json{{"error", "item not found"}, {"item_id", itemId}};

        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};

        // Shared item-describer — used for the queried item AND for whatever is
        // currently equipped in the compare slot(s), so stats/ilvl line up for
        // side-by-side comparison.
        auto describeItem = [](ItemTemplate const* p) -> nlohmann::json {
            nlohmann::json j;
            j["id"]             = p->ItemId;
            j["name"]           = p->Name1;
            j["quality"]        = p->Quality;
            j["item_level"]     = p->ItemLevel;
            j["required_level"] = p->RequiredLevel;
            j["class"]          = p->Class;
            j["subclass"]       = p->SubClass;
            j["inventory_type"] = p->InventoryType;
            j["bonding"]        = p->Bonding;
            if (p->Armor)  j["armor"]    = p->Armor;
            if (p->Delay)  j["delay_ms"] = p->Delay;
            if (p->Damage[0].DamageMin > 0.0f || p->Damage[0].DamageMax > 0.0f)
            {
                j["damage_min"]  = p->Damage[0].DamageMin;
                j["damage_max"]  = p->Damage[0].DamageMax;
                j["damage_type"] = p->Damage[0].DamageType;
            }
            if (p->Block) j["block"] = p->Block;

            // Stats: only emit non-zero entries and only up to StatsCount. A skipped
            // entry is normal (weapons with 0 primary stats); an empty array means
            // "item has no stats", not "we couldn't parse".
            nlohmann::json stats = nlohmann::json::array();
            for (uint32 i = 0; i < p->StatsCount && i < MAX_ITEM_PROTO_STATS; ++i)
            {
                if (p->ItemStat[i].ItemStatValue == 0) continue;
                stats.push_back({{"type",  p->ItemStat[i].ItemStatType},
                                 {"value", p->ItemStat[i].ItemStatValue}});
            }
            if (!stats.empty()) j["stats"] = std::move(stats);
            return j;
        };

        nlohmann::json out = describeItem(proto);

        // CanUseItem covers class/race/level/skill gates. We expose the enum value as
        // `can_use_reason_code` when non-OK so the agent doesn't have to guess — it can
        // map common codes (EQUIP_ERR_CANT_EQUIP_LEVEL_I=33, _CANT_EQUIP_SKILL=38, etc.)
        // to actionable hints.
        InventoryResult canUse = bot->CanUseItem(proto);
        out["can_use"] = (canUse == EQUIP_ERR_OK);
        if (canUse != EQUIP_ERR_OK)
            out["can_use_reason_code"] = static_cast<int>(canUse);

        out["already_owned"] = bot->GetItemCount(itemId, /*inBankAlso=*/false);

        // Map InventoryType → equipment slot(s) for compare. Items with 2 candidate
        // slots (rings, trinkets, off-hand-capable weapons) get both so the agent sees
        // whichever is currently worse — the usual swap target.
        auto slotsForInvType = [](uint32 invType) -> std::vector<uint8> {
            switch (invType)
            {
                case INVTYPE_HEAD:           return {EQUIPMENT_SLOT_HEAD};
                case INVTYPE_NECK:           return {EQUIPMENT_SLOT_NECK};
                case INVTYPE_SHOULDERS:      return {EQUIPMENT_SLOT_SHOULDERS};
                case INVTYPE_BODY:           return {EQUIPMENT_SLOT_BODY};
                case INVTYPE_CHEST:
                case INVTYPE_ROBE:           return {EQUIPMENT_SLOT_CHEST};
                case INVTYPE_WAIST:          return {EQUIPMENT_SLOT_WAIST};
                case INVTYPE_LEGS:           return {EQUIPMENT_SLOT_LEGS};
                case INVTYPE_FEET:           return {EQUIPMENT_SLOT_FEET};
                case INVTYPE_WRISTS:         return {EQUIPMENT_SLOT_WRISTS};
                case INVTYPE_HANDS:          return {EQUIPMENT_SLOT_HANDS};
                case INVTYPE_FINGER:         return {EQUIPMENT_SLOT_FINGER1, EQUIPMENT_SLOT_FINGER2};
                case INVTYPE_TRINKET:        return {EQUIPMENT_SLOT_TRINKET1, EQUIPMENT_SLOT_TRINKET2};
                case INVTYPE_CLOAK:          return {EQUIPMENT_SLOT_BACK};
                case INVTYPE_2HWEAPON:
                case INVTYPE_WEAPONMAINHAND: return {EQUIPMENT_SLOT_MAINHAND};
                case INVTYPE_WEAPONOFFHAND:
                case INVTYPE_SHIELD:
                case INVTYPE_HOLDABLE:       return {EQUIPMENT_SLOT_OFFHAND};
                case INVTYPE_WEAPON:         return {EQUIPMENT_SLOT_MAINHAND, EQUIPMENT_SLOT_OFFHAND};
                case INVTYPE_RANGED:
                case INVTYPE_RANGEDRIGHT:
                case INVTYPE_THROWN:
                case INVTYPE_RELIC:          return {EQUIPMENT_SLOT_RANGED};
                case INVTYPE_TABARD:         return {EQUIPMENT_SLOT_TABARD};
                default:                     return {};
            }
        };
        auto slotName = [](uint8 s) -> const char* {
            switch (s)
            {
                case EQUIPMENT_SLOT_HEAD:      return "head";
                case EQUIPMENT_SLOT_NECK:      return "neck";
                case EQUIPMENT_SLOT_SHOULDERS: return "shoulders";
                case EQUIPMENT_SLOT_BODY:      return "body";
                case EQUIPMENT_SLOT_CHEST:     return "chest";
                case EQUIPMENT_SLOT_WAIST:     return "waist";
                case EQUIPMENT_SLOT_LEGS:      return "legs";
                case EQUIPMENT_SLOT_FEET:      return "feet";
                case EQUIPMENT_SLOT_WRISTS:    return "wrists";
                case EQUIPMENT_SLOT_HANDS:     return "hands";
                case EQUIPMENT_SLOT_FINGER1:   return "finger1";
                case EQUIPMENT_SLOT_FINGER2:   return "finger2";
                case EQUIPMENT_SLOT_TRINKET1:  return "trinket1";
                case EQUIPMENT_SLOT_TRINKET2:  return "trinket2";
                case EQUIPMENT_SLOT_BACK:      return "back";
                case EQUIPMENT_SLOT_MAINHAND:  return "mainhand";
                case EQUIPMENT_SLOT_OFFHAND:   return "offhand";
                case EQUIPMENT_SLOT_RANGED:    return "ranged";
                case EQUIPMENT_SLOT_TABARD:    return "tabard";
                default:                       return "unknown";
            }
        };

        auto slots = slotsForInvType(proto->InventoryType);
        if (!slots.empty())
        {
            nlohmann::json cmp = nlohmann::json::array();
            for (uint8 s : slots)
            {
                nlohmann::json slotEntry;
                slotEntry["slot"]      = s;
                slotEntry["slot_name"] = slotName(s);
                if (Item* cur = bot->GetItemByPos(INVENTORY_SLOT_BAG_0, s))
                {
                    if (ItemTemplate const* cp = cur->GetTemplate())
                        slotEntry["equipped"] = describeItem(cp);
                    else
                        slotEntry["equipped"] = nullptr;
                }
                else
                {
                    // Empty slot is useful info ("just slot-in, no swap needed") so we
                    // keep it in the response instead of hiding it behind an "if".
                    slotEntry["equipped"] = nullptr;
                }
                cmp.push_back(std::move(slotEntry));
            }
            out["compare_equipped"] = std::move(cmp);
        }

        return out;
    }

    nlohmann::json Tool_GetNearbyPlayers(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot || !bot->IsInWorld()) return nlohmann::json{{"error", "bot not in world"}};

        float radius = static_cast<float>(args.value("radius", 60.0));
        if (radius <= 0.0f || radius > 1000.0f) radius = 60.0f;

        nlohmann::json arr = nlohmann::json::array();
        for (auto const& pair : ObjectAccessor::GetPlayers())
        {
            Player* other = pair.second;
            if (!other || other == bot || !other->IsInWorld()) continue;
            if (bot->GetDistance(other) > radius) continue;
            // Exclude bots so the list stays useful for "who real is around me".
            bool isBot = PlayerbotsMgr::instance().GetPlayerbotAI(other) != nullptr;
            arr.push_back({
                {"name",   other->GetName()},
                {"level",  other->GetLevel()},
                {"class",  FormatClassLocal(other->getClass())},
                {"race",   FormatRaceLocal(other->getRace())},
                {"distance", static_cast<int>(bot->GetDistance(other))},
                {"x", other->GetPositionX()},
                {"y", other->GetPositionY()},
                {"z", other->GetPositionZ()},
                {"is_bot", isBot}
            });
        }
        return nlohmann::json{
            {"radius", radius},
            {"count",  arr.size()},
            {"players", std::move(arr)}
        };
    }

    nlohmann::json Tool_GetGroup(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found"}};

        Group* grp = bot->GetGroup();
        if (!grp) return nlohmann::json{{"in_group", false}};

        nlohmann::json members = nlohmann::json::array();
        for (GroupReference const* ref = grp->GetFirstMember(); ref; ref = ref->next())
        {
            Player* m = ref->GetSource();
            if (!m) continue;
            members.push_back({
                {"name",   m->GetName()},
                {"level",  m->GetLevel()},
                {"class",  FormatClassLocal(m->getClass())},
                {"role",   m == grp->GetLeader() ? "leader" : "member"},
                {"is_bot", PlayerbotsMgr::instance().GetPlayerbotAI(m) != nullptr}
            });
        }
        return nlohmann::json{
            {"in_group", true},
            {"is_raid",  grp->isRaidGroup()},
            {"size",     members.size()},
            {"members",  std::move(members)}
        };
    }

    nlohmann::json Tool_GetTarget(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found"}};

        Unit* victim = bot->GetVictim();
        if (!victim) return nlohmann::json{{"has_target", false}};

        return nlohmann::json{
            {"has_target", true},
            {"name",       victim->GetName()},
            {"level",      victim->GetLevel()},
            {"health_pct", victim->GetHealthPct()},
            {"is_player",  victim->GetTypeId() == TYPEID_PLAYER},
            {"distance",   static_cast<int>(bot->GetDistance(victim))}
        };
    }

    static const char* ReactStateString(ReactStates s)
    {
        switch (s) {
            case REACT_PASSIVE:    return "passive";
            case REACT_DEFENSIVE:  return "defensive";
            case REACT_AGGRESSIVE: return "aggressive";
            default:               return "unknown";
        }
    }

    static const char* CommandStateString(CommandStates s)
    {
        switch (s) {
            case COMMAND_STAY:    return "stay";
            case COMMAND_FOLLOW:  return "follow";
            case COMMAND_ATTACK:  return "attack";
            case COMMAND_ABANDON: return "abandon";
            default:              return "unknown";
        }
    }

    nlohmann::json DescribePetCreature(Player* bot, Creature* c, const char* type)
    {
        nlohmann::json j;
        j["type"]   = type;
        j["entry"]  = c->GetEntry();
        j["name"]   = c->GetName();
        j["level"]  = c->GetLevel();
        j["alive"]  = c->IsAlive();
        j["health"] = c->GetHealth();
        j["max_health"] = c->GetMaxHealth();
        j["health_pct"] = c->GetHealthPct();
        j["react_state"] = ReactStateString(c->GetReactState());
        if (CharmInfo* ci = c->GetCharmInfo())
            j["command_state"] = CommandStateString(ci->GetCommandState());
        else
            j["command_state"] = "unknown";
        if (bot && bot->IsInWorld() && c->IsInWorld() && bot->GetMapId() == c->GetMapId())
            j["distance"] = static_cast<int>(bot->GetDistance(c));
        return j;
    }

    // Read-only companion to bot_pet_command. Reports the bot's pet plus any
    // controlled non-totem guardians (mage water elemental, shaman fire/earth/air,
    // DK ghoul, druid treants), so the agent can decide whether to issue pet
    // orders and verify the state change after one.
    nlohmann::json Tool_GetBotPet(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};

        nlohmann::json pets = nlohmann::json::array();

        if (Pet* pet = bot->GetPet())
            pets.push_back(DescribePetCreature(bot, pet, "pet"));

        // Mirrors PetsAction::Execute filtering: scan m_Controlled, skip the
        // primary pet (already added) and any totems (totem stance is irrelevant —
        // they fire-and-forget, and the playerbot `pet` verb ignores them too).
        for (Unit* u : bot->m_Controlled)
        {
            Creature* c = dynamic_cast<Creature*>(u);
            if (!c) continue;
            if (bot->GetPet() && c == bot->GetPet()) continue;
            if (c->IsTotem()) continue;
            pets.push_back(DescribePetCreature(bot, c, "guardian"));
        }

        return nlohmann::json{
            {"has_pet", !pets.empty()},
            {"count",   pets.size()},
            {"pets",    std::move(pets)}
        };
    }

    nlohmann::json Tool_GetInventory(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found"}};

        // Iterate the main backpack (slots 23..38 in INVENTORY_SLOT_BAG_0)
        // plus any equipped bags. Aggregate by item entry to keep payload short.
        std::unordered_map<uint32, uint32> counts; // item_id → count

        auto scanBag = [&](uint8 bag, uint8 endSlot) {
            for (uint8 slot = 0; slot < endSlot; ++slot)
            {
                Item* it = bot->GetItemByPos(bag, slot);
                if (!it) continue;
                counts[it->GetEntry()] += it->GetCount();
            }
        };

        // Main backpack first
        for (uint8 slot = INVENTORY_SLOT_ITEM_START; slot < INVENTORY_SLOT_ITEM_END; ++slot)
        {
            Item* it = bot->GetItemByPos(INVENTORY_SLOT_BAG_0, slot);
            if (!it) continue;
            counts[it->GetEntry()] += it->GetCount();
        }
        // Equipped bags 19..22 → bag-slots 0..N
        for (uint8 bag = INVENTORY_SLOT_BAG_START; bag < INVENTORY_SLOT_BAG_END; ++bag)
        {
            if (Bag* pBag = bot->GetBagByPos(bag))
                scanBag(bag, pBag->GetBagSize());
        }

        nlohmann::json items = nlohmann::json::array();
        for (auto const& [id, count] : counts)
        {
            nlohmann::json entry{{"item_id", id}, {"count", count}};
            if (ItemTemplate const* t = sObjectMgr->GetItemTemplate(id))
            {
                entry["name"]    = t->Name1;
                entry["quality"] = t->Quality;
            }
            items.push_back(entry);
        }
        return nlohmann::json{
            {"distinct_items", items.size()},
            {"items", std::move(items)}
        };
    }

    // Bank-side counterpart to Tool_GetInventory. The bot's personal bank lives in
    // two disjoint slot ranges: the 28 fixed main-bank slots (BANK_SLOT_ITEM_START..
    // BANK_SLOT_ITEM_END inside INVENTORY_SLOT_BAG_0) and the 7 bank bag containers
    // (BANK_SLOT_BAG_START..BANK_SLOT_BAG_END), each an equipped Bag* with its own
    // inner slot range. Aggregates by item entry just like get_inventory so the
    // payload stays compact, plus surfaces capacity counters so the agent can plan
    // deposit/withdraw without a separate "is the bank full?" probe. Sparse
    // soulbound flag lets the agent route mail-to-alts decisions correctly — a
    // BoP item read from bank cannot be mailed even by the owner.
    nlohmann::json Tool_GetBotBank(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found"}};

        std::unordered_map<uint32, uint32> counts;
        std::unordered_set<uint32> soulbound;
        uint32 mainUsed = 0;
        uint32 bankBagsEquipped = 0;
        uint32 bankBagItemsUsed = 0;
        uint32 bankBagCapacityTotal = 0;

        for (uint8 slot = BANK_SLOT_ITEM_START; slot < BANK_SLOT_ITEM_END; ++slot)
        {
            Item* it = bot->GetItemByPos(INVENTORY_SLOT_BAG_0, slot);
            if (!it) continue;
            ++mainUsed;
            counts[it->GetEntry()] += it->GetCount();
            if (it->IsSoulBound()) soulbound.insert(it->GetEntry());
        }

        for (uint8 bag = BANK_SLOT_BAG_START; bag < BANK_SLOT_BAG_END; ++bag)
        {
            Bag* pBag = bot->GetBagByPos(bag);
            if (!pBag) continue;
            ++bankBagsEquipped;
            bankBagCapacityTotal += pBag->GetBagSize();
            for (uint8 sl = 0; sl < pBag->GetBagSize(); ++sl)
            {
                Item* it = bot->GetItemByPos(bag, sl);
                if (!it) continue;
                ++bankBagItemsUsed;
                counts[it->GetEntry()] += it->GetCount();
                if (it->IsSoulBound()) soulbound.insert(it->GetEntry());
            }
        }

        nlohmann::json items = nlohmann::json::array();
        for (auto const& [id, count] : counts)
        {
            nlohmann::json entry{{"item_id", id}, {"count", count}};
            if (ItemTemplate const* t = sObjectMgr->GetItemTemplate(id))
            {
                entry["name"]    = t->Name1;
                entry["quality"] = t->Quality;
            }
            if (soulbound.count(id)) entry["soulbound"] = true;
            items.push_back(std::move(entry));
        }

        return nlohmann::json{
            {"distinct_items", items.size()},
            {"main_slots_used", mainUsed},
            {"main_slots_total", static_cast<uint32>(BANK_SLOT_ITEM_END - BANK_SLOT_ITEM_START)},
            {"bank_bags_equipped", bankBagsEquipped},
            {"bank_bag_slots_total", static_cast<uint32>(BANK_SLOT_BAG_END - BANK_SLOT_BAG_START)},
            {"bank_bag_items_used", bankBagItemsUsed},
            {"bank_bag_capacity_total", bankBagCapacityTotal},
            {"items", std::move(items)}
        };
    }

    // Bot-side mirror of get_player_gear. The existing get_player_gear tool resolves a
    // target by player guid/name and works for any Player* — including bots — but its
    // schema (PlayerGuidProp) and description ("a player's equipped gear") have steered
    // the agent to treat it as master-only, the same way get_player_quests vs
    // get_bot_quests split worked out. This handler returns ALL 19 equipment slots,
    // including empties (the player-gear tool silently skips empty slots, so the agent
    // can't see vacant rings/cloak/trinkets without subtracting from a known full set).
    // Pairs with get_inventory + get_item_details + bot_equip_item to close the
    // gear-replacement decision loop.
    nlohmann::json Tool_GetBotGear(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found"}};

        // EQUIPMENT_SLOT_BODY (3) is the cosmetic shirt; EQUIPMENT_SLOT_TABARD (18) is
        // the guild tabard. Names match the wowhead/wowwiki convention so the agent
        // can cross-reference without translating numeric slots.
        static char const* const SLOT_NAMES[EQUIPMENT_SLOT_END] = {
            "head",      "neck",      "shoulders", "shirt",    "chest",
            "waist",     "legs",      "feet",      "wrists",   "hands",
            "finger1",   "finger2",   "trinket1",  "trinket2", "back",
            "main_hand", "off_hand",  "ranged",    "tabard"
        };

        nlohmann::json slots = nlohmann::json::array();
        nlohmann::json emptySlots = nlohmann::json::array();
        uint32 sum = 0;
        uint32 filled = 0;

        for (uint8 slot = EQUIPMENT_SLOT_START; slot < EQUIPMENT_SLOT_END; ++slot)
        {
            nlohmann::json entry;
            entry["slot"]      = slot;
            entry["slot_name"] = SLOT_NAMES[slot];

            Item* it = bot->GetItemByPos(INVENTORY_SLOT_BAG_0, slot);
            if (it && it->GetTemplate())
            {
                ItemTemplate const* t = it->GetTemplate();
                entry["is_empty"]       = false;
                entry["item_id"]        = it->GetEntry();
                entry["name"]           = t->Name1;
                entry["item_lvl"]       = t->ItemLevel;
                entry["quality"]        = t->Quality;
                entry["required_level"] = t->RequiredLevel;
                if (uint32 ench = it->GetEnchantmentId(PERM_ENCHANTMENT_SLOT))
                    entry["perm_enchant_id"] = ench;
                if (it->IsSoulBound())
                    entry["soulbound"] = true;

                sum += t->ItemLevel;
                ++filled;
            }
            else
            {
                entry["is_empty"] = true;
                emptySlots.push_back(SLOT_NAMES[slot]);
            }
            slots.push_back(std::move(entry));
        }

        nlohmann::json out;
        out["name"]             = bot->GetName();
        out["class"]            = FormatClassLocal(bot->getClass());
        out["level"]            = bot->GetLevel();
        out["equipped_pieces"]  = filled;
        out["empty_slot_count"] = emptySlots.size();
        if (!emptySlots.empty()) out["empty_slots"] = std::move(emptySlots);
        if (filled > 0)          out["avg_item_level"] = sum / filled;
        out["slots"] = std::move(slots);
        return out;
    }

    // --- PR8c action tools (gated by g_McpAllowActionTools) ---

    // Prepend playerbot's configured CommandPrefix (e.g., "!") so HandleCommand
    // doesn't silently drop the message. PlayerbotAI.cpp:935 enforces:
    //   if (text.find(commandPrefix) != 0) return;
    // — meaning bare "emote dance" is dropped when CommandPrefix="!". Idempotent:
    // skips prefixing if the text already starts with the prefix.
    static std::string ApplyPlayerbotPrefix(const std::string& text)
    {
        const std::string& prefix = sPlayerbotAIConfig.commandPrefix;
        if (prefix.empty()) return text;
        if (text.size() >= prefix.size() && text.compare(0, prefix.size(), prefix) == 0)
            return text;
        return prefix + text;
    }

    // Dispatch a textual playerbot command on behalf of a master player. Uses
    // PlayerbotAI::HandleCommand (the same entry the chat parser uses for
    // ".playerbot OPERATOR follow"). Returns ok/error JSON. Also writes an audit row
    // when EnableAudit=1 so .ollama gateway costs sees action tool usage.
// Bots told "stay" whose next "follow" must not be deduped away (2026-09-25,
// E2E S9): after "stay" the bot is usually still within 20 yd of the player and
// a follow fired < 90 s ago, so bot_follow's two dedups turned "Raz follow" into
// an ok-noop and Raz stayed put. Set on a dispatched "stay", cleared on "follow".
static std::mutex s_stayingMutex;
static std::unordered_set<uint64_t> s_stayingBots;

    nlohmann::json DispatchBotChatCommand(uint64_t botGuid, uint64_t masterGuid, const std::string& text)
    {
        if (!g_McpAllowActionTools)
            return nlohmann::json{{"error", "action tools disabled (set OllamaChat.Mcp.AllowActionTools = 1)"}};

        if (text.empty())
            return nlohmann::json{{"error", "empty command"}};

        auto t0 = std::chrono::steady_clock::now();
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};

        PlayerbotAI* ai = PlayerbotsMgr::instance().GetPlayerbotAI(bot);
        if (!ai)  return nlohmann::json{{"error", "target is not a bot (no PlayerbotAI)"}};

        Player* master = (masterGuid != 0)
            ? ObjectAccessor::FindPlayer(ObjectGuid(masterGuid))
            : nullptr;
        // PlayerbotAI::HandleCommand wants a non-null fromPlayer for the security
        // check, and a BOT issuer fails it silently (peer bots aren't authorized).
        // The MCP bridge strips undeclared args, so masterGuid is 0 on virtually
        // every external tool call — resolve a REAL issuer instead of
        // self-mastering (which made every dispatched verb a silent no-op):
        //   1. the bot's own registered playerbot master (the fleet leader),
        //   2. else the SystemMasterGuid session (Botmaster/Overlord) — same
        //      fallback leader_admin_command already uses,
        //   3. else the bot itself (pre-existing last resort).
        if (!master)
        {
            if (Player* own = ai->GetMaster(); own && own->IsInWorld())
                master = own;
        }
        if (!master && g_McpLeaderSystemMasterGuid)
        {
            ObjectGuid sysGuid(HighGuid::Player, g_McpLeaderSystemMasterGuid);
            Player* sys = ObjectAccessor::FindConnectedPlayer(sysGuid);
            if (sys && sys->IsInWorld() && sys->GetSession())
                master = sys;
        }
        if (!master) master = bot;
        uint32_t masterAccount = (master && master->GetSession()) ? master->GetSession()->GetAccountId() : 0;

        std::string prefixed = ApplyPlayerbotPrefix(text);

        bool didThrow = false;
        try {
            // PlayerbotAI has two HandleCommand overloads — the public one takes
            // Player* (pointer), the private one takes Player& (reference). The
            // signature here picks the public overload at PlayerbotAI.h:393.
            ai->HandleCommand(CHAT_MSG_WHISPER, prefixed, master);
        } catch (const std::exception& e) {
            didThrow = true;
            WriteGatewayAuditRecord(botGuid, masterGuid, masterAccount,
                                    static_cast<uint32_t>(text.size()), 0, 0, 0,
                                    static_cast<uint32_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                        std::chrono::steady_clock::now() - t0).count()),
                                    "mcp:action", true);
            return nlohmann::json{{"error", std::string("playerbots threw: ") + e.what()}};
        }
        WriteGatewayAuditRecord(botGuid, masterGuid, masterAccount,
                                static_cast<uint32_t>(text.size()), 0, 0, 0,
                                static_cast<uint32_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                    std::chrono::steady_clock::now() - t0).count()),
                                "mcp:action", didThrow);
        LOG_INFO("server.loading", "[Ollama Chat MCP] action dispatched: bot={} text='{}'", botGuid, text);
        {
            std::lock_guard<std::mutex> lock(s_stayingMutex);
            if (text == "stay")
                s_stayingBots.insert(botGuid);
            else if (text == "follow" || text.rfind("follow ", 0) == 0)
                s_stayingBots.erase(botGuid);
        }
        return nlohmann::json{{"ok", true}, {"command", text}};
    }

    // Per-bot dedup for bot_follow. Each successful dispatch makes playerbot whisper
    // "Following X" to the master (FollowAction::TellMaster), so tactical's 10s
    // re-sync ticks become whisper spam. Returns ok-noop on dedup so the tactical
    // model doesn't see an error and retry.
    static std::mutex s_lastFollowMutex;
    static std::unordered_map<uint64_t, std::chrono::steady_clock::time_point> s_lastFollowAt;

    nlohmann::json Tool_BotFollow(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_follow"))
            return nlohmann::json{{"error", "rate-limited"}};

        std::string target = args.value("name", std::string{});

        // Idempotency: skip if already physically close to the follow target.
        // Tactical's follow re-sync would otherwise refire every heartbeat just because
        // the model defaulted to bot_follow without checking distance.
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        Player* whisperer = (playerGuid != 0) ? ObjectAccessor::FindPlayer(ObjectGuid(playerGuid)) : nullptr;
        Player* followTarget = whisperer;
        if (!target.empty())
        {
            if (Player* namedTarget = ObjectAccessor::FindPlayerByName(target))
                followTarget = namedTarget;
        }

        bool staying;
        {
            std::lock_guard<std::mutex> lock(s_stayingMutex);
            staying = s_stayingBots.count(botGuid) > 0;
        }
        // A bot told to stay must get the follow even when close or recently
        // followed — both dedups below assume it is already following.
        if (!staying && bot && followTarget && bot->IsInWorld() && followTarget->IsInWorld()
            && bot->GetMapId() == followTarget->GetMapId()
            && bot->GetDistance(followTarget) < 20.0f)
        {
            return nlohmann::json{{"ok", true}, {"noop", "already close to follow target (<20y)"}};
        }

        // 90s minimum gap (was 30s). Each successful dispatch makes playerbot whisper
        // "Following X" via TellMaster, so high-frequency tactical re-syncs become
        // chat spam. ok-noop on dedup so the model doesn't see error and retry.
        {
            auto now = std::chrono::steady_clock::now();
            std::lock_guard<std::mutex> lock(s_lastFollowMutex);
            auto it = s_lastFollowAt.find(botGuid);
            if (!staying && it != s_lastFollowAt.end())
            {
                auto gapSec = std::chrono::duration_cast<std::chrono::seconds>(now - it->second).count();
                if (gapSec < 90)
                    return nlohmann::json{{"ok", true}, {"noop", "follow throttled (last fire " + std::to_string(gapSec) + "s ago, min 90s)"}};
            }
            s_lastFollowAt[botGuid] = now;
        }
        // Empty target → follow whoever asked (the whisperer's name).
        if (target.empty() && whisperer)
            target = whisperer->GetName();
        // Still empty → bare "follow", which FollowAction resolves to the bot's
        // REGISTERED master (PlayerbotAI::master). With no master that is a
        // silent no-op — refuse honestly instead of returning a false ok.
        if (target.empty())
        {
            PlayerbotAI* ai = bot ? PlayerbotsMgr::instance().GetPlayerbotAI(bot) : nullptr;
            Player* followMaster = ai ? ai->GetMaster() : nullptr;
            if (!followMaster || !followMaster->IsInWorld())
                return nlohmann::json{{"error",
                    "no follow target: pass 'name', or wire the bot's master "
                    "(is the fleet party formed? see OllamaChat.Fleet.EnsureParty)"}};
        }
        std::string cmd = target.empty() ? std::string{"follow"} : ("follow " + target);
        return DispatchBotChatCommand(botGuid, playerGuid, cmd);
    }

    nlohmann::json Tool_BotStay(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& /*args*/)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_stay"))
            return nlohmann::json{{"error", "rate-limited"}};
        return DispatchBotChatCommand(botGuid, playerGuid, "stay");
    }

    nlohmann::json Tool_BotEmote(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_emote"))
            return nlohmann::json{{"error", "rate-limited"}};
        std::string emote = args.value("emote", std::string{});
        if (emote.empty()) return nlohmann::json{{"error", "missing 'emote' (e.g., 'bow', 'wave', 'cheer')"}};
        // Sanitise the emote name to avoid command-injection back into the chat parser.
        for (char c : emote)
            if (!std::isalnum(static_cast<unsigned char>(c)) && c != '_')
                return nlohmann::json{{"error", "emote must be alphanumeric"}};
        return DispatchBotChatCommand(botGuid, playerGuid, "emote " + emote);
    }

    using OllamaChat::Fleet::ClearPendingInvite;

    nlohmann::json Tool_BotInviteToGroup(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_invite_to_group"))
            return nlohmann::json{{"error", "rate-limited"}};
        std::string target = args.value("name", std::string{});
        if (target.empty() && playerGuid != 0)
        {
            Player* p = ObjectAccessor::FindPlayer(ObjectGuid(playerGuid));
            if (p) target = p->GetName();
        }
        if (target.empty()) return nlohmann::json{{"error", "missing 'name' and no whisperer in context"}};

        // Direct join for a whitelisted human. The playerbots `invite <name>`
        // text command reports ok but sends nothing from a self-mastered fleet
        // leader (measured 2026-09-24: three "invites", no popup). The operator
        // asked the bot to invite them, so add them to the bot's group directly
        // (creating it if needed); Fleet.EnsureParty then makes them the bots'
        // master. Runs on the world thread (group APIs are not thread-safe).
        if (!g_McpAllowActionTools)
            return nlohmann::json{{"error", "action tools disabled (set OllamaChat.Mcp.AllowActionTools = 1)"}};
        nlohmann::json direct = OllamaChat::WorldTask::Run([botGuid, target]() -> nlohmann::json
        {
            Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
            Player* human = ObjectAccessor::FindPlayerByName(target, /*checkInWorld=*/true);
            if (!bot || !bot->IsInWorld() || !PlayerbotsMgr::instance().GetPlayerbotAI(bot))
                return nlohmann::json{{"error", "botGuid is not an online playerbot"}};
            if (!human || human == bot || !IsWhitelistedHumanPlayer(human, /*anyHumanWhenNoWhitelist=*/false))
                return nlohmann::json{{"fallback", true}};
            if (human->GetGroup())
                return nlohmann::json{{"error", target + " is already in a group — they can /invite " + bot->GetName() + " instead"}};
            if (OllamaChat::Fleet::IsBattleGroup(bot->GetGroup()))
                return nlohmann::json{{"error", bot->GetName() + " is in a battleground — invite after the match"}};
            Group* group = bot->GetGroup();
            if (!group)
            {
                ClearPendingInvite(bot);
                group = new Group();
                if (!group->Create(bot))
                {
                    delete group;
                    return nlohmann::json{{"error", "could not create a group"}};
                }
                sGroupMgr->AddGroup(group);
            }
            if (group->IsFull())
                return nlohmann::json{{"error", "group is full"}};
            ClearPendingInvite(human, group);
            if (!group->AddMember(human))
                return nlohmann::json{{"error", "could not add " + target + " to the group"}};
            return nlohmann::json{{"ok", true}, {"joined", target}, {"group_leader", bot->GetName()},
                                  {"note", "added directly (no invite popup)"}};
        });
        if (!direct.value("fallback", false))
            return direct;
        return DispatchBotChatCommand(botGuid, playerGuid, "invite " + target);
    }

    // (2026-09-24) Point a bot's playerbots master at a named online player, so it
    // follows and obeys them. Missing during the first live party session — the
    // only code that set masters was Fleet.EnsureParty, which always chose the
    // fleet leader. `name` defaults to the whisperer.
    nlohmann::json Tool_BotSetMaster(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!g_McpAllowActionTools)
            return nlohmann::json{{"error", "action tools disabled (set OllamaChat.Mcp.AllowActionTools = 1)"}};
        std::string name = args.value("name", std::string{});
        return OllamaChat::WorldTask::Run([botGuid, playerGuid, name]() -> nlohmann::json
        {
            // Fleet bots only: they are random-bot-holder bots (Overlord
            // AutoSpawnBots), whose masters RandomPlayerbotMgr clears on the
            // master's logout. A bot in another player's PlayerbotMgr would keep
            // a dangling master pointer after the new master logs out (codex).
            const uint32_t low = static_cast<uint32_t>(botGuid);
            // Party guests (promotion.h) count as fleet: they share the
            // operator's group, and Promotion::Tick masters them the same way.
            const bool fleetBot = low == g_FleetLeaderGuid ||
                std::find(g_FleetMemberGuidList.begin(), g_FleetMemberGuidList.end(), low) != g_FleetMemberGuidList.end() ||
                OllamaChat::Promotion::IsPartyGuest(botGuid);
            if (!fleetBot)
                return nlohmann::json{{"error", "only fleet bots (Fleet.LeaderGuid / Fleet.MemberGuids) or party guests can be re-mastered"}};
            Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
            if (!bot || !bot->IsInWorld()) return nlohmann::json{{"error", "bot not in world"}};
            PlayerbotAI* ai = PlayerbotsMgr::instance().GetPlayerbotAI(bot);
            if (!ai) return nlohmann::json{{"error", "not a playerbot"}};
            Player* master = !name.empty() ? ObjectAccessor::FindPlayerByName(name, /*checkInWorld=*/true)
                           : playerGuid != 0 ? ObjectAccessor::FindPlayer(ObjectGuid(playerGuid)) : nullptr;
            if (!master || !master->IsInWorld()) return nlohmann::json{{"error", "master not found or not online"}};
            if (!OllamaChat::Fleet::IsSafeMaster(bot, master))
                return nlohmann::json{{"error", "bot is held by another player's PlayerbotMgr — re-mastering it would leave a dangling pointer"}};
            Player* prev = ai->GetMaster();
            std::string previous = prev ? prev->GetName() : std::string{};
            ai->SetMaster(master);
            return nlohmann::json{{"ok", true}, {"bot", bot->GetName()}, {"master", master->GetName()}, {"previous_master", previous},
                                  {"note", "Fleet.EnsureParty re-applies its own rule every interval: the human in the fleet group, else the fleet leader"}};
        });
    }

    // (2026-09-24) Run one worldserver console (GM) command and return its output.
    // Missing during the first live party session (no way to `.group join` the
    // operator). Queued through the core's CLI queue, so it executes on the world
    // thread with console privileges; the first token must be in
    // OllamaChat.Mcp.Gm.AllowedCommands because the in-game model sees this tool.
    namespace
    {
        struct GmCmdState
        {
            std::mutex m;
            std::condition_variable cv;
            std::string out;
            bool done = false;
            bool success = false;
        };
    }

    nlohmann::json Tool_AdminGmCommand(uint64_t /*botGuid*/, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!g_McpAllowActionTools)
            return nlohmann::json{{"error", "action tools disabled (set OllamaChat.Mcp.AllowActionTools = 1)"}};
        std::string command = args.value("command", std::string{});
        while (!command.empty() && (command.front() == '.' || std::isspace(static_cast<unsigned char>(command.front()))))
            command.erase(command.begin());
        if (command.empty()) return nlohmann::json{{"error", "missing 'command', e.g. 'lookup item hearthstone' or 'pinfo Slayo'"}};
        if (command.find('\n') != std::string::npos || command.find('\r') != std::string::npos)
            return nlohmann::json{{"error", "one command per call"}};

        // Allowlist matches whole leading WORDS ("tele name" admits "tele name
        // Slayo Undercity" but not "tele del Undercity") — codex review: a
        // first-token check let `tele del` delete a shared teleport location.
        std::string lower;
        for (char c : command) lower.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
        bool allowed = false;
        for (const auto& v : g_McpGmAllowedCommandsList)
            if (lower == v || (lower.size() > v.size() && lower.compare(0, v.size(), v) == 0 && lower[v.size()] == ' '))
            { allowed = true; break; }
        if (!allowed)
            return nlohmann::json{{"error", "GM command not in allowlist (OllamaChat.Mcp.Gm.AllowedCommands, whole-word prefixes)"}};

        // The callback owns one reference to the state, so a timed-out call here
        // never leaves the world thread writing into freed memory.
        auto state = std::make_shared<GmCmdState>();
        auto* holderRef = new std::shared_ptr<GmCmdState>(state);
        auto print = [](void* arg, std::string_view text)
        {
            auto& st = **static_cast<std::shared_ptr<GmCmdState>*>(arg);
            std::lock_guard<std::mutex> lk(st.m);
            if (st.out.size() < 16384) st.out.append(text.data(), text.size());
        };
        auto finished = [](void* arg, bool success)
        {
            auto* ref = static_cast<std::shared_ptr<GmCmdState>*>(arg);
            {
                std::lock_guard<std::mutex> lk((*ref)->m);
                (*ref)->success = success;
                (*ref)->done = true;
            }
            (*ref)->cv.notify_all();
            delete ref;
        };
        sWorld->QueueCliCommand(new CliCommandHolder(holderRef, command.c_str(), print, finished));

        std::unique_lock<std::mutex> lk(state->m);
        if (!state->cv.wait_for(lk, std::chrono::seconds(8), [&] { return state->done; }))
            return nlohmann::json{{"ok", false}, {"command", command}, {"error", "timed out after 8s (still queued on the world thread)"},
                                  {"output", state->out}};
        return nlohmann::json{{"ok", state->success}, {"command", command}, {"output", state->out}};
    }

    // (2026-09-24) Put an online player into another online character's group
    // (creating that character's group if needed). The console `group join`
    // is Console::No on this core, so it is done here, on the world thread.
    nlohmann::json Tool_AdminGroupJoin(uint64_t /*botGuid*/, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!g_McpAllowActionTools)
            return nlohmann::json{{"error", "action tools disabled (set OllamaChat.Mcp.AllowActionTools = 1)"}};
        std::string who = args.value("name", std::string{});
        std::string into = args.value("group_of", std::string{});
        if (who.empty() || into.empty()) return nlohmann::json{{"error", "need 'name' (who joins) and 'group_of' (whose group)"}};
        return OllamaChat::WorldTask::Run([who, into]() -> nlohmann::json
        {
            Player* p = ObjectAccessor::FindPlayerByName(who, true);
            Player* owner = ObjectAccessor::FindPlayerByName(into, true);
            if (!p || !owner) return nlohmann::json{{"error", "both characters must be online"}};
            if (p == owner) return nlohmann::json{{"error", "name and group_of are the same character"}};
            if (p->GetGroup()) return nlohmann::json{{"error", who + " is already in a group"}};
            if (OllamaChat::Fleet::IsBattleGroup(owner->GetGroup()))
                return nlohmann::json{{"error", into + " is in a battleground group"}};
            Group* group = owner->GetGroup();
            if (!group)
            {
                ClearPendingInvite(owner);
                group = new Group();
                if (!group->Create(owner)) { delete group; return nlohmann::json{{"error", "could not create a group"}}; }
                sGroupMgr->AddGroup(group);
            }
            if (group->IsFull()) return nlohmann::json{{"error", "group is full"}};
            ClearPendingInvite(p, group);
            if (!group->AddMember(p)) return nlohmann::json{{"error", "AddMember failed"}};
            return nlohmann::json{{"ok", true}, {"joined", who}, {"group_of", into},
                                  {"members", group->GetMembersCount()}};
        });
    }

    // (2026-09-24) Where is a character — map/zone/area/coords, group and master.
    // The console `gps` is Console::No on this core.
    // (2026-09-25) The tactical snapshot was only ever in the model's prompt;
    // the audit table has the action, not what the model saw. Read-only.
    nlohmann::json Tool_AdminTacticalState(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        nlohmann::json st = GetTacticalDebugState(botGuid);
        if (st.empty()) return nlohmann::json{{"error", "no tactical tick recorded for this bot since startup"}};
        st["botGuid"] = botGuid;
        return st;
    }

    nlohmann::json Tool_AdminTacticalForce(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!g_McpAllowActionTools)
            return nlohmann::json{{"error", "action tools disabled (set OllamaChat.Mcp.AllowActionTools = 1)"}};
        return SetTacticalForcedAction(botGuid, args.value("action", std::string{}), args.value("ticks", 3));
    }

    // (2026-09-25) Seed / inspect / reset a character's quest state, so a turn-in
    // can be tested end to end and repeatedly (the E2E harness). Fleet bots and
    // the E2E account only — never an operator character's progress.
    nlohmann::json Tool_AdminQuestState(uint64_t /*botGuid*/, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!g_McpAllowActionTools)
            return nlohmann::json{{"error", "action tools disabled (set OllamaChat.Mcp.AllowActionTools = 1)"}};
        std::string name = args.value("name", std::string{});
        uint32_t questId = args.value("quest_id", 0u);
        std::string mode = args.value("mode", std::string("status"));
        if (name.empty() || !questId) return nlohmann::json{{"error", "need name and quest_id"}};
        return OllamaChat::WorldTask::Run([name, questId, mode]() -> nlohmann::json
        {
            Player* p = ObjectAccessor::FindPlayerByName(name, /*checkInWorld=*/true);
            if (!p) return nlohmann::json{{"error", name + " not online"}};
            const uint32_t low = p->GetGUID().GetCounter();
            const bool fleet = low == g_FleetLeaderGuid ||
                std::find(g_FleetMemberGuidList.begin(), g_FleetMemberGuidList.end(), low) != g_FleetMemberGuidList.end();
            if (mode != "status" && !fleet && PlayerbotsMgr::instance().GetPlayerbotAI(p) == nullptr)
                return nlohmann::json{{"error", "only fleet bots can be changed (status works for anyone)"}};
            Quest const* q = sObjectMgr->GetQuestTemplate(questId);
            if (!q) return nlohmann::json{{"error", "unknown quest_id"}};
            // Active attempt first; the reward marker only when there is none — a
            // repeatable keeps IsQuestRewarded() across later attempts (codex).
            auto status = [p, questId]() {
                switch (p->GetQuestStatus(questId))
                {
                    case QUEST_STATUS_NONE:
                        return std::string(p->IsQuestRewarded(questId) ? "rewarded" : "none");
                    case QUEST_STATUS_REWARDED: return std::string("rewarded");
                    case QUEST_STATUS_COMPLETE: return std::string("complete");
                    case QUEST_STATUS_INCOMPLETE: return std::string("incomplete");
                    case QUEST_STATUS_FAILED: return std::string("failed");
                    default: return std::string("other");
                }
            };
            const std::string before = status();
            // Abandon the way WorldSession::HandleQuestLogRemoveQuest does: source
            // items, quest items, status AND the quest-log slot (RemoveActiveQuest
            // alone leaves the slot occupied — codex).
            auto abandon = [p, questId]()
            {
                if (p->GetQuestStatus(questId) == QUEST_STATUS_NONE) return true;
                if (!p->TakeQuestSourceItem(questId, true)) return false;
                if (Quest const* tq = sObjectMgr->GetQuestTemplate(questId))
                    if (tq->HasSpecialFlag(QUEST_SPECIAL_FLAGS_TIMED))
                        p->RemoveTimedQuest(questId);   // else m_timedquests keeps blocking timed quests (codex)
                p->AbandonQuest(questId);
                p->RemoveActiveQuest(questId);
                uint16 slot = p->FindQuestSlot(questId);
                if (slot < MAX_QUEST_LOG_SIZE) p->SetQuestSlot(slot, 0);
                return true;
            };
            if (mode == "reset")
            {
                if (!abandon()) return nlohmann::json{{"error", "cannot take back the quest's source item"}};
                if (p->IsQuestRewarded(questId)) p->RemoveRewardedQuest(questId);   // covers repeatables (codex)
            }
            else if (mode == "complete")
            {
                // Capacity first: never drop a rewarded record and then fail (codex).
                // "Needs a slot" = not in the log yet — a rewarded quest reads as
                // QUEST_STATUS_REWARDED here, not NONE (codex).
                if (p->FindQuestSlot(questId) >= MAX_QUEST_LOG_SIZE && p->FindQuestSlot(0) >= MAX_QUEST_LOG_SIZE)
                    return nlohmann::json{{"error", "quest log is full"}};
                if (p->IsQuestRewarded(questId)) p->RemoveRewardedQuest(questId);   // covers repeatables (codex)
                if (p->GetQuestStatus(questId) == QUEST_STATUS_NONE)
                {
                    p->AddQuest(q, nullptr);
                    if (p->GetQuestStatus(questId) == QUEST_STATUS_NONE)
                        return nlohmann::json{{"error", "AddQuest did not take the quest"}};
                }
                p->CompleteQuest(questId);
            }
            else if (mode != "status")
                return nlohmann::json{{"error", "mode must be status, complete or reset"}};
            return nlohmann::json{{"ok", true}, {"name", p->GetName()}, {"quest_id", questId},
                                  {"title", q->GetTitle()}, {"before", before}, {"after", status()}};
        });
    }

    nlohmann::json Tool_AdminPlayerGps(uint64_t /*botGuid*/, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        std::string who = args.value("name", std::string{});
        if (who.empty()) return nlohmann::json{{"error", "missing 'name'"}};
        return OllamaChat::WorldTask::Run([who]() -> nlohmann::json
        {
            Player* p = ObjectAccessor::FindPlayerByName(who, true);
            if (!p) return nlohmann::json{{"error", who + " not online"}};
            nlohmann::json r{{"name", p->GetName()}, {"map", p->GetMapId()}, {"zone", p->GetZoneId()}, {"area", p->GetAreaId()},
                             {"x", p->GetPositionX()}, {"y", p->GetPositionY()}, {"z", p->GetPositionZ()},
                             {"alive", p->IsAlive()}, {"in_combat", p->IsInCombat()}};
            if (Group* g = p->GetGroup())
            {
                nlohmann::json members = nlohmann::json::array();
                for (GroupReference* ref = g->GetFirstMember(); ref; ref = ref->next())
                    if (Player* m = ref->GetSource()) members.push_back(m->GetName());
                r["group"] = {{"leader_guid", g->GetLeaderGUID().GetCounter()}, {"members", members}};
            }
            if (PlayerbotAI* ai = PlayerbotsMgr::instance().GetPlayerbotAI(p))
                r["master"] = ai->GetMaster() ? ai->GetMaster()->GetName() : std::string{};
            return r;
        });
    }

    nlohmann::json Tool_BotUseItem(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_use_item"))
            return nlohmann::json{{"error", "rate-limited"}};
        if (!args.contains("item_id") || !args["item_id"].is_number())
            return nlohmann::json{{"error", "missing numeric 'item_id'"}};
        uint32 id = args["item_id"].get<uint32>();
        return DispatchBotChatCommand(botGuid, playerGuid, "use " + std::to_string(id));
    }

    // --- Container/lootable opening cluster ---
    // Playerbot's `open items` verb fires use on every container in the bot's bags in
    // one batch (clams, gift packages, lockboxes, herbalism/mining/skinning bags, holiday
    // packages — anything with ITEM_FLAG_HAS_LOOT). Without this, the agent had to call
    // bot_use_item once per container, which spams dispatch slots and rate limits when a
    // bot accumulates 20+ openables after a long grind. Pair with get_bot_openables (read)
    // so the agent can preview what will be opened — including locked entries (LockID>0)
    // that need lockpicking skill or a key and would be silently skipped.

    struct OpenableInfo
    {
        uint32      itemId;
        std::string name;
        uint32      quality;
        uint32      totalCount;
        bool        hasLock;
    };

    static std::vector<OpenableInfo> CollectBotOpenables(Player* bot)
    {
        std::unordered_map<uint32, OpenableInfo> agg;

        auto consider = [&](Item* it) {
            if (!it) return;
            ItemTemplate const* t = it->GetTemplate();
            if (!t) return;
            if (!t->HasFlag(ITEM_FLAG_HAS_LOOT)) return;
            auto& slot = agg[t->ItemId];
            slot.itemId      = t->ItemId;
            slot.name        = t->Name1;
            slot.quality     = t->Quality;
            slot.hasLock     = (t->LockID > 0);
            slot.totalCount += it->GetCount();
        };

        for (uint8 slot = INVENTORY_SLOT_ITEM_START; slot < INVENTORY_SLOT_ITEM_END; ++slot)
            consider(bot->GetItemByPos(INVENTORY_SLOT_BAG_0, slot));
        for (uint8 bag = INVENTORY_SLOT_BAG_START; bag < INVENTORY_SLOT_BAG_END; ++bag)
        {
            if (Bag* pBag = bot->GetBagByPos(bag))
                for (uint8 sl = 0; sl < pBag->GetBagSize(); ++sl)
                    consider(bot->GetItemByPos(bag, sl));
        }

        std::vector<OpenableInfo> out;
        out.reserve(agg.size());
        for (auto& [_, info] : agg)
            out.push_back(std::move(info));
        return out;
    }

    nlohmann::json Tool_GetBotOpenables(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};

        auto openables = CollectBotOpenables(bot);
        uint32 totalCount  = 0;
        uint32 lockedCount = 0;
        nlohmann::json items = nlohmann::json::array();
        for (auto const& info : openables)
        {
            items.push_back({
                {"item_id",  info.itemId},
                {"name",     info.name},
                {"quality",  info.quality},
                {"count",    info.totalCount},
                {"has_lock", info.hasLock},
            });
            totalCount += info.totalCount;
            if (info.hasLock) lockedCount += info.totalCount;
        }
        return nlohmann::json{
            {"distinct_openables", openables.size()},
            {"total_count",        totalCount},
            {"locked_count",       lockedCount},
            {"items",              std::move(items)},
        };
    }

    nlohmann::json Tool_BotOpenItems(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& /*args*/)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_open_items"))
            return nlohmann::json{{"error", "rate-limited"}};

        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};

        // Pre-flight so the agent gets a structured "nothing to open" rather than a
        // silent dispatch no-op. Echo the openable counts back alongside the dispatch
        // envelope so the agent can confirm the action targeted the expected stack
        // without re-querying get_bot_openables right after.
        auto openables = CollectBotOpenables(bot);
        if (openables.empty())
            return nlohmann::json{
                {"ok",             false},
                {"error",          "nothing_openable"},
                {"openable_count", 0},
            };

        uint32 totalCount = 0;
        for (auto const& info : openables) totalCount += info.totalCount;

        nlohmann::json out = DispatchBotChatCommand(botGuid, playerGuid, "open items");
        out["openable_count"]    = totalCount;
        out["distinct_openables"] = openables.size();
        return out;
    }

    nlohmann::json Tool_BotCast(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_cast"))
            return nlohmann::json{{"error", "rate-limited"}};
        if (!args.contains("spell_id") || !args["spell_id"].is_number())
            return nlohmann::json{{"error", "missing numeric 'spell_id'"}};
        uint32 id = args["spell_id"].get<uint32>();
        return DispatchBotChatCommand(botGuid, playerGuid, "cast " + std::to_string(id));
    }

    // Wraps playerbot `pet <verb>` (PetsAction). Handles every case the
    // playerbot pet verb does: stance set (aggressive/defensive/passive),
    // stance query (the "stance" subcommand reports current per-pet states
    // back via TellMaster), and command state (attack/follow/stay).
    // No-op against a bot without a pet — playerbot tells the master
    // "You have no pet or guardian pet." and we return ok with the same
    // command echo as other action tools.
    nlohmann::json Tool_BotPetCommand(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_pet_command"))
            return nlohmann::json{{"error", "rate-limited"}};
        std::string command = args.value("command", std::string{});
        if (command.empty())
            return nlohmann::json{{"error", "missing 'command' (one of: aggressive, defensive, passive, stance, attack, follow, stay)"}};
        static const std::set<std::string> kValid = {
            "aggressive", "defensive", "passive", "stance", "attack", "follow", "stay"
        };
        if (!kValid.count(command))
            return nlohmann::json{{"error", "invalid 'command' — must be one of: aggressive, defensive, passive, stance, attack, follow, stay"}};
        return DispatchBotChatCommand(botGuid, playerGuid, "pet " + command);
    }

    // Permanently abandon (delete) the bot's current hunter pet — the pet-management sibling of
    // bot_tame_pet. Wraps mod-playerbots' `tame abandon` verb (TameAction -> AbandonPet), which
    // calls bot->RemovePet(pet, PET_SAVE_AS_DELETED) on the bot's current pet iff it is a
    // HUNTER_PET; a non-hunter (or a hunter with no pet) has nothing to abandon and the engine
    // silently no-ops. Because DispatchBotChatCommand reports ok-on-dispatch even when the engine
    // no-ops, this tool first pre-flights the SAME condition the engine checks (bot->GetPet() is a
    // live HUNTER_PET) so the agent gets a real no-pet signal instead of a false ok. The pet name
    // is captured before dispatch (the pet is gone afterward) and echoed back. Frees the pet slot
    // before taming a better species with bot_tame_pet, or drops a low-quality random-family tame.
    // Permanently deletes the pet (the bot must re-tame to recover) -> destructive.
    nlohmann::json Tool_BotAbandonPet(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& /*args*/)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_abandon_pet"))
            return nlohmann::json{{"error", "rate-limited"}};

        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};
        if (!bot->IsInWorld())
            return nlohmann::json{{"error", "bot not in world"}};

        // Mirror TameAction::AbandonPet's own guard: only a live HUNTER_PET can be abandoned.
        // GetPet() is exactly what the engine inspects, so this pre-flight matches it 1:1 and
        // subsumes the not-a-hunter case (a non-hunter never owns a HUNTER_PET). Without it,
        // `tame abandon` silently no-ops while DispatchBotChatCommand still returns ok.
        Pet* pet = bot->GetPet();
        if (!pet || pet->getPetType() != HUNTER_PET)
            return nlohmann::json{{"error", "bot has no hunter pet to abandon"}};
        std::string petName = pet->GetName();  // capture before the pet is deleted

        auto result = DispatchBotChatCommand(botGuid, playerGuid, "tame abandon");
        if (result.contains("ok"))
        {
            result["action"] = "abandon_pet";
            result["pet_name"] = petName;
        }
        return result;
    }

    // Rename the bot's current hunter pet — the cosmetic pet-management sibling of bot_tame_pet /
    // bot_abandon_pet, and the last unexposed `tame` sub-form. Wraps mod-playerbots' `tame rename
    // <name>` verb (TameAction -> RenamePet), which renames the bot's CURRENT pet: the engine
    // requires a 1-12 character, alphabetic-only name, capitalizes the first letter, rejects
    // reserved names, then SetName + SavePetToDB + SendPetNameQuery (re-casting Call Pet so the
    // new name shows immediately). Only a hunter with a live pet can rename; a non-hunter (or a
    // hunter with no pet) has nothing to rename and the engine silently no-ops. Because
    // DispatchBotChatCommand reports ok-on-dispatch even when the engine no-ops, this tool
    // pre-flights the SAME condition the engine checks (bot->GetPet() is a live HUNTER_PET) plus
    // the engine's own 1-12 / alphabetic-only rule, so the agent gets a real signal instead of a
    // false ok. The alphabetic-only guard also keeps the name single-token, so it cannot inject a
    // second `tame` sub-command or a different verb. Reserved-name rejection stays engine-side.
    // Cosmetic + reversible (rename again) -> not destructive.
    nlohmann::json Tool_BotRenamePet(uint64_t botGuid, uint64_t playerGuid, const nlohmann::json& args)
    {
        if (!TryClaimActionRateSlot(botGuid, "bot_rename_pet"))
            return nlohmann::json{{"error", "rate-limited"}};

        std::string name = args.value("name", std::string{});
        if (name.empty())
            return nlohmann::json{{"error", "missing 'name'"}};
        // Mirror RenamePet's own rule: pet names are 1-12 letters, alphabetic-only. Enforcing it
        // here gives the agent a real validation error (the engine only TellError's it, invisible
        // to MCP) AND keeps the arg single-token so it can't inject a second `tame` sub-command.
        if (name.size() > 12)
            return nlohmann::json{{"error", "'name' too long — pet names are 1-12 characters"}};
        for (char c : name)
            if (!std::isalpha(static_cast<unsigned char>(c)))
                return nlohmann::json{{"error", "'name' must be alphabetic only (letters a-z / A-Z)"}};

        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot) return nlohmann::json{{"error", "bot not found / offline"}};
        if (!bot->IsInWorld())
            return nlohmann::json{{"error", "bot not in world"}};

        // Mirror TameAction::RenamePet's implicit guard: only a live HUNTER_PET can be renamed.
        // GetPet() is exactly what the engine inspects, so this matches it 1:1 and subsumes the
        // not-a-hunter case (a non-hunter never owns a HUNTER_PET). Without it, `tame rename`
        // silently no-ops while DispatchBotChatCommand still returns ok.
        Pet* pet = bot->GetPet();
        if (!pet || pet->getPetType() != HUNTER_PET)
            return nlohmann::json{{"error", "bot has no hunter pet to rename"}};
        std::string oldName = pet->GetName();  // capture before the rename

        auto result = DispatchBotChatCommand(botGuid, playerGuid, "tame rename " + name);
        if (result.contains("ok"))
        {
            // The engine capitalizes the first letter of the stored name — reflect that in the
            // echoed new_name so it matches what get_bot_pet will report.
            std::string storedName = name;
            storedName[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(storedName[0])));
            result["action"] = "rename_pet";
            result["old_name"] = oldName;
            result["new_name"] = storedName;
        }
        return result;
    }

    // --- Tier 9: Leader Bot ---

    // First-token denylist match (case-insensitive). e.g. "logout 5" matches "logout".
    bool IsLeaderCommandDenied(const std::string& cmd)
    {
        if (g_McpLeaderDeniedCommandsList.empty()) return false;
        std::string head;
        head.reserve(cmd.size());
        for (char c : cmd)
        {
            if (std::isspace(static_cast<unsigned char>(c))) break;
            head.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
        }
        for (const auto& denied : g_McpLeaderDeniedCommandsList)
            if (head == denied) return true;
        return false;
    }

    // Enumerate candidate target players for the given leader, branching on g_McpLeaderScope.
    // Always excludes the leader itself. Filters by IsInWorld. Returns empty on bad scope.
    std::vector<Player*> ResolveLeaderTargets(Player* leader)
    {
        std::vector<Player*> out;
        if (!leader || !leader->IsInWorld()) return out;

        // Include the leader itself first so leader_command_all broadcasts (accept,
        // drink, eat, follow, attack, maintenance, etc.) actually hit the leader
        // and not just the rest of the squad. Per-tool dispatch handles the
        // self-vs-peer issuer routing in DispatchLeaderCommand.
        out.push_back(leader);

        if (g_McpLeaderScope == "group")
        {
            // No early return when ungrouped: party guests are appended below.
            if (Group* g = leader->GetGroup())
                for (GroupReference const* ref = g->GetFirstMember(); ref; ref = ref->next())
                {
                    Player* m = ref->GetSource();
                    if (!m || m == leader || !m->IsInWorld()) continue;
                    out.push_back(m);
                }
        }
        else if (g_McpLeaderScope == "nearby")
        {
            for (auto const& pair : ObjectAccessor::GetPlayers())
            {
                Player* p = pair.second;
                if (!p || p == leader || !p->IsInWorld()) continue;
                if (leader->GetDistance(p) > g_McpLeaderNearbyRadius) continue;
                out.push_back(p);
            }
        }
        else if (g_McpLeaderScope == "owner")
        {
            if (!leader->GetSession()) return out;
            uint32_t leaderAcct = leader->GetSession()->GetAccountId();
            for (auto const& pair : ObjectAccessor::GetPlayers())
            {
                Player* p = pair.second;
                if (!p || p == leader || !p->IsInWorld() || !p->GetSession()) continue;
                if (p->GetSession()->GetAccountId() != leaderAcct) continue;
                out.push_back(p);
            }
        }
        else if (g_McpLeaderScope == "all")
        {
            for (auto const& pair : ObjectAccessor::GetPlayers())
            {
                Player* p = pair.second;
                if (!p || p == leader || !p->IsInWorld()) continue;
                out.push_back(p);
            }
        }

        // Party guests (promotion.h) join the fleet: bots the operator invited
        // into THEIR group answer the leader's commands even when the leader is
        // not in that group.
        for (uint64_t guest : OllamaChat::Promotion::PartyGuests())
        {
            Player* p = ObjectAccessor::FindPlayer(ObjectGuid(guest));
            if (!p || p == leader || !p->IsInWorld()) continue;
            if (std::find(out.begin(), out.end(), p) == out.end())
                out.push_back(p);
        }
        return out;
    }

    // Mirror of DispatchBotChatCommand but the issuer is the leader bot (not the master).
    // Audit channel is "mcp:leader" so .ollama gateway costs sees it separately.
    nlohmann::json DispatchLeaderCommand(uint64_t leaderGuid, uint64_t targetBotGuid, const std::string& text)
    {
        if (!g_McpLeaderEnable)
            return nlohmann::json{{"error", "leader mode disabled (set OllamaChat.Mcp.Leader.Enable = 1)"}};
        if (!IsLeaderBot(leaderGuid))
            return nlohmann::json{{"error", "bot not authorized as leader (Mcp.Leader.BotGUIDs)"}};
        if (text.empty())
            return nlohmann::json{{"error", "empty command"}};
        if (IsLeaderCommandDenied(text))
            return nlohmann::json{{"error", "command starts with a denied verb (Mcp.Leader.DeniedCommands)"}};

        auto t0 = std::chrono::steady_clock::now();
        Player* leader = ObjectAccessor::FindPlayer(ObjectGuid(leaderGuid));
        if (!leader || !leader->IsInWorld())
            return nlohmann::json{{"error", "leader bot not in world"}};
        Player* target = ObjectAccessor::FindPlayer(ObjectGuid(targetBotGuid));
        if (!target || !target->IsInWorld())
            return nlohmann::json{{"error", "target not in world"}};

        // Scope check: target must be reachable from this leader given current g_McpLeaderScope.
        bool inScope = false;
        for (Player* p : ResolveLeaderTargets(leader))
            if (p == target) { inScope = true; break; }
        if (!inScope)
            return nlohmann::json{{"error", "target not in leader scope"}};

        PlayerbotAI* targetAI = PlayerbotsMgr::instance().GetPlayerbotAI(target);
        if (!targetAI)
            return nlohmann::json{{"error", "target is not a bot (no PlayerbotAI)"}};

        uint32_t leaderAccount = (leader->GetSession()) ? leader->GetSession()->GetAccountId() : 0;

        std::string prefixed = ApplyPlayerbotPrefix(text);

        // PlayerbotAI::HandleCommand runs a security check on `fromPlayer` against
        // the receiving bot — non-master peers (e.g. another bot in the group, like
        // a leader bot) typically fail PLAYERBOT_SECURITY_INVITE and the function
        // returns silently. The receiver then doesn't react. Pass the LEADER'S
        // master (the human who claimed the leader via AutoClaim) as fromPlayer so
        // the receiver sees the human as issuer — security check passes and the
        // command actually runs. Falls back to the leader itself if no master.
        Player* issuer = leader;
        if (PlayerbotAI* leaderAI = PlayerbotsMgr::instance().GetPlayerbotAI(leader))
            if (Player* lm = leaderAI->GetMaster())
                if (lm != leader && lm->IsInWorld())
                    issuer = lm;
        // Party guest (promotion.h): its master is the operator it is grouped
        // with, not the leader's — issue as that human, or playerbots' security
        // check drops the command silently while we report ok (codex review).
        if (OllamaChat::Promotion::IsPartyGuest(targetBotGuid))
        {
            Player* gm = targetAI->GetMaster();
            if (!gm || gm == target || !gm->IsInWorld() || PlayerbotsMgr::instance().GetPlayerbotAI(gm))
                return nlohmann::json{{"error", "party guest has no human master yet — retry in a few seconds"}};
            issuer = gm;
        }

        bool didThrow = false;
        try {
            targetAI->HandleCommand(CHAT_MSG_WHISPER, prefixed, issuer);
        } catch (const std::exception& e) {
            didThrow = true;
            WriteGatewayAuditRecord(leaderGuid, targetBotGuid, leaderAccount,
                                    static_cast<uint32_t>(text.size()), 0, 0, 0,
                                    static_cast<uint32_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                        std::chrono::steady_clock::now() - t0).count()),
                                    "mcp:leader", true);
            return nlohmann::json{{"error", std::string("playerbots threw: ") + e.what()}};
        }
        WriteGatewayAuditRecord(leaderGuid, targetBotGuid, leaderAccount,
                                static_cast<uint32_t>(text.size()), 0, 0, 0,
                                static_cast<uint32_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                    std::chrono::steady_clock::now() - t0).count()),
                                "mcp:leader", didThrow);
        LOG_INFO("server.loading", "[Ollama Chat MCP Leader] dispatched: leader={} target={} text='{}'",
                 leaderGuid, targetBotGuid, text);
        return nlohmann::json{
            {"ok", true},
            {"target", target->GetName()},
            {"command", text}
        };
    }

    nlohmann::json Tool_LeaderListTargets(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        if (!g_McpLeaderEnable)
            return nlohmann::json{{"error", "leader mode disabled (set OllamaChat.Mcp.Leader.Enable = 1)"}};
        if (!IsLeaderBot(leaderGuid))
            return nlohmann::json{{"error", "bot not authorized as leader (Mcp.Leader.BotGUIDs)"}};

        Player* leader = ObjectAccessor::FindPlayer(ObjectGuid(leaderGuid));
        if (!leader || !leader->IsInWorld())
            return nlohmann::json{{"error", "leader not in world"}};

        nlohmann::json arr = nlohmann::json::array();
        for (Player* t : ResolveLeaderTargets(leader))
        {
            if (!t) continue;
            bool isBot = PlayerbotsMgr::instance().GetPlayerbotAI(t) != nullptr;
            arr.push_back({
                {"guid",     t->GetGUID().GetCounter()},
                {"name",     t->GetName()},
                {"class",    FormatClassLocal(t->getClass())},
                {"level",    t->GetLevel()},
                {"is_bot",   isBot},
                {"in_combat", t->IsInCombat()},
                {"hp_pct",   t->GetHealthPct()},
                {"distance", leader->GetDistance(t)}
            });
        }
        return nlohmann::json{
            {"scope",  g_McpLeaderScope},
            {"leader", {{"guid", leaderGuid}, {"name", leader->GetName()}}},
            {"count",  arr.size()},
            {"targets", arr}
        };
    }

    nlohmann::json Tool_LeaderCommand(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!TryClaimLeaderRateSlot(leaderGuid))
            return nlohmann::json{{"error", "rate-limited"}};

        std::string targetName = args.value("targetBotName", std::string{});
        std::string command    = args.value("command", std::string{});
        if (targetName.empty()) return nlohmann::json{{"error", "missing 'targetBotName'"}};
        if (command.empty())    return nlohmann::json{{"error", "missing 'command'"}};

        Player* leader = ObjectAccessor::FindPlayer(ObjectGuid(leaderGuid));
        if (!leader || !leader->IsInWorld())
            return nlohmann::json{{"error", "leader not in world"}};

        Player* target = nullptr;
        for (Player* t : ResolveLeaderTargets(leader))
            if (t && t->GetName() == targetName) { target = t; break; }
        if (!target)
            return nlohmann::json{{"error", "target not found in scope: " + targetName}};

        return DispatchLeaderCommand(leaderGuid, target->GetGUID().GetCounter(), command);
    }

    nlohmann::json Tool_LeaderCommandAll(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!TryClaimLeaderRateSlot(leaderGuid))
            return nlohmann::json{{"error", "rate-limited"}};
        std::string command = args.value("command", std::string{});
        if (command.empty()) return nlohmann::json{{"error", "missing 'command'"}};

        Player* leader = ObjectAccessor::FindPlayer(ObjectGuid(leaderGuid));
        if (!leader || !leader->IsInWorld())
            return nlohmann::json{{"error", "leader not in world"}};

        nlohmann::json results = nlohmann::json::array();
        size_t okCount = 0, errCount = 0;
        for (Player* t : ResolveLeaderTargets(leader))
        {
            if (!t) continue;
            // Broadcasts only target bots (real players in scope are noise).
            if (!PlayerbotsMgr::instance().GetPlayerbotAI(t)) continue;
            auto r = DispatchLeaderCommand(leaderGuid, t->GetGUID().GetCounter(), command);
            results.push_back(r);
            if (r.contains("ok") && r["ok"].is_boolean() && r["ok"].get<bool>()) ++okCount;
            else ++errCount;
        }
        return nlohmann::json{
            {"issued", command},
            {"ok_count", okCount},
            {"err_count", errCount},
            {"results", results}
        };
    }

    // Phase 3 safety — panic-button wrapper over leader_command_all("stay"). Having a
    // dedicated "stop" tool makes the agent's escape hatch unambiguous; the LLM doesn't
    // have to remember the playerbot verb grammar during an incident.
    nlohmann::json Tool_EmergencyStop(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& /*args*/)
    {
        if (!TryClaimLeaderRateSlot(leaderGuid))
            return nlohmann::json{{"error", "rate-limited"}};

        Player* leader = ObjectAccessor::FindPlayer(ObjectGuid(leaderGuid));
        if (!leader || !leader->IsInWorld())
            return nlohmann::json{{"error", "leader not in world"}};

        nlohmann::json results = nlohmann::json::array();
        size_t okCount = 0, errCount = 0;
        for (Player* t : ResolveLeaderTargets(leader))
        {
            if (!t) continue;
            if (!PlayerbotsMgr::instance().GetPlayerbotAI(t)) continue;
            auto r = DispatchLeaderCommand(leaderGuid, t->GetGUID().GetCounter(), "stay");
            results.push_back(r);
            if (r.contains("ok") && r["ok"].is_boolean() && r["ok"].get<bool>()) ++okCount;
            else ++errCount;
        }
        LOG_INFO("server.loading",
                 "[Ollama Chat MCP] emergency_stop fired by leader={} affected={}/{}",
                 leaderGuid, okCount, okCount + errCount);
        return nlohmann::json{
            {"issued", "stay"},
            {"ok_count", okCount},
            {"err_count", errCount},
            {"results", results}
        };
    }

    nlohmann::json Tool_LeaderAdminCommand(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!g_McpLeaderEnable)
            return nlohmann::json{{"error", "leader mode disabled (set OllamaChat.Mcp.Leader.Enable = 1)"}};
        if (!IsLeaderBot(leaderGuid))
            return nlohmann::json{{"error", "bot not authorized as leader (Mcp.Leader.BotGUIDs)"}};
        if (!g_McpLeaderAllowAdminCommands)
            return nlohmann::json{{"error", "admin commands disabled (set OllamaChat.Mcp.Leader.AllowAdminCommands = 1)"}};
        if (!TryClaimLeaderRateSlot(leaderGuid))
            return nlohmann::json{{"error", "rate-limited"}};

        std::string command = args.value("command", std::string{});
        if (command.empty())
            return nlohmann::json{{"error", "missing 'command' (e.g. 'add OPERATOR', 'remove *', 'addclass mage', 'list')"}};

        // First-token allowlist check.
        std::string head;
        for (char c : command)
        {
            if (std::isspace(static_cast<unsigned char>(c))) break;
            head.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
        }
        bool allowed = false;
        for (const auto& v : g_McpLeaderAllowedAdminCommandsList)
            if (head == v) { allowed = true; break; }
        if (!allowed)
            return nlohmann::json{{"error", "admin verb '" + head + "' not in allowlist (Mcp.Leader.AllowedAdminCommands)"}};

        auto t0 = std::chrono::steady_clock::now();
        Player* leader = ObjectAccessor::FindPlayer(ObjectGuid(leaderGuid));
        if (!leader || !leader->IsInWorld())
            return nlohmann::json{{"error", "leader not in world"}};

        // `.playerbots bot` requires a real (non-bot) master session: PlayerbotsMgr::GetPlayerbotMgr
        // returns nullptr for bots (gated by !IsBotAI()), so dispatching via the bot's own session
        // fails with "You cannot control bots yet". Route through the leader's master instead —
        // that's the human player who spawned/owns the leader bot.
        PlayerbotAI* leaderAI = PlayerbotsMgr::instance().GetPlayerbotAI(leader);
        Player* master = leaderAI ? leaderAI->GetMaster() : nullptr;
        bool usedSystemFallback = false;

        // Phase 1.2 — fallback. rndbots (e.g. leaders auto-spawned by Overlord) have no
        // per-bot master. When Mcp.Leader.SystemMasterGuid points at a registered master
        // (typically Overlord), dispatch through that session instead so the agent can
        // drive admin commands without any human in-world.
        //
        // `via_system_master:true` FORCES that route even when the leader has a master.
        // Since #422 Fleet.EnsureParty makes the leader self-mastered, so the fallback
        // below never fires on its own — and `remove *` dispatched through the leader's
        // OWN session removes only the leader's bots, while the fleet actually lives in
        // the Overlord's PlayerbotMgr (the session AutoSpawnBots added them from). The
        // symptom is ok:true with nothing despawned (measured 2026-09-20). Forcing the
        // system master is how a reroll despawns the whole fleet in one call.
        const bool forceSystemMaster = args.value("via_system_master", false);
        if (forceSystemMaster && !g_McpLeaderSystemMasterGuid)
            return nlohmann::json{{"error", "via_system_master requested but Mcp.Leader.SystemMasterGuid is 0"}};
        if ((forceSystemMaster || !master || !master->IsInWorld() || !master->GetSession()) && g_McpLeaderSystemMasterGuid)
        {
            ObjectGuid sysGuid(HighGuid::Player, g_McpLeaderSystemMasterGuid);
            Player* sys = ObjectAccessor::FindConnectedPlayer(sysGuid);
            if (sys && sys->IsInWorld() && sys->GetSession()
                && PlayerbotsMgr::instance().GetPlayerbotMgr(sys))
            {
                master = sys;
                usedSystemFallback = true;
            }
        }
        // Forced route must not degrade to the leader's own session silently — that is
        // the exact wrong-session dispatch the flag exists to avoid.
        if (forceSystemMaster && !usedSystemFallback)
            return nlohmann::json{{"error",
                "via_system_master: the SystemMasterGuid character is not in world with a PlayerbotMgr "
                "(is the Overlord logged in?)"}, {"system_master_guid", g_McpLeaderSystemMasterGuid}};

        if (!master || !master->IsInWorld() || !master->GetSession())
            return nlohmann::json{{"error",
                "leader has no master session and no SystemMasterGuid fallback is available "
                "(set OllamaChat.Mcp.Leader.SystemMasterGuid to an in-world master's guid, e.g. Overlord)"}};

        ChatHandler handler(master->GetSession());
        // ChatHandler::ParseCommands gates on a leading '.' or '!' (Chat.cpp:247) and
        // returns false immediately otherwise — a bare "playerbots bot ..." string
        // never even reaches the command table. The leading dot is stripped by
        // ParseCommands itself before dispatch, so this mirrors normal GM chat input.
        std::string fullCommand = ".playerbots bot " + command;

        bool ok = false;
        bool didThrow = false;
        uint32_t masterAccount = master->GetSession()->GetAccountId();
        try {
            ok = handler.ParseCommands(fullCommand);
        } catch (const std::exception& e) {
            didThrow = true;
            WriteGatewayAuditRecord(leaderGuid, 0, masterAccount,
                                    static_cast<uint32_t>(fullCommand.size()), 0, 0, 0,
                                    static_cast<uint32_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                        std::chrono::steady_clock::now() - t0).count()),
                                    "mcp:leader_admin", true);
            return nlohmann::json{{"error", std::string("ChatHandler threw: ") + e.what()}};
        }

        WriteGatewayAuditRecord(leaderGuid, 0, masterAccount,
                                static_cast<uint32_t>(fullCommand.size()), 0, 0, 0,
                                static_cast<uint32_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                    std::chrono::steady_clock::now() - t0).count()),
                                "mcp:leader_admin", didThrow || !ok);
        LOG_INFO("server.loading",
                 "[Ollama Chat MCP Leader Admin] dispatched: leader={} master={} {} command='{}' ok={}",
                 leaderGuid, master->GetGUID().GetCounter(),
                 usedSystemFallback ? "(system-fallback)" : "(leader-master)",
                 fullCommand, ok);
        return nlohmann::json{
            {"ok", ok},
            {"dispatched", fullCommand},
            {"master", master->GetName()},
            {"via_system_fallback", usedSystemFallback}
        };
    }

    // Permanent character deletion through the ENGINE's own path — the same call
    // `.character erase` makes (cs_character.cpp HandleCharacterEraseCommand):
    // Player::DeleteFromDB(lowGuid, accountId, updateRealmChars=true, deleteFinally=true).
    // That is what makes it correct where a DB-side wipe is not: DeleteFromDB walks
    // every character table, detaches guild/group/mail/arena state, fires
    // OnPlayerDelete, and clears sCharacterCache — so the NAME is immediately free
    // for re-creation. A SQL delete leaves the cache stale and the client refuses
    // the old name as "taken" until the next worldserver restart (the exact case
    // this was built for: a from-scratch reroll that reuses the leader's name).
    //
    // Unlike the GM command this REFUSES an online character instead of kicking it:
    // an Overlord-spawned bot's kick races its own logout-save, which can re-insert
    // rows after the delete. Despawn first (leader_admin_command 'remove <name>').
    nlohmann::json Tool_LeaderAdminDeleteCharacter(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!g_McpLeaderEnable)
            return nlohmann::json{{"error", "leader mode disabled (set OllamaChat.Mcp.Leader.Enable = 1)"}};
        if (!IsLeaderBot(leaderGuid))
            return nlohmann::json{{"error", "bot not authorized as leader (Mcp.Leader.BotGUIDs)"}};
        if (!g_McpLeaderAllowAdminCommands)
            return nlohmann::json{{"error", "admin commands disabled (set OllamaChat.Mcp.Leader.AllowAdminCommands = 1)"}};
        if (!TryClaimLeaderRateSlot(leaderGuid))
            return nlohmann::json{{"error", "rate-limited"}};

        // Resolve the target by name or guid, through the character cache (authoritative
        // for "does this character exist" without a DB round-trip).
        ObjectGuid target;
        const std::string name = args.value("name", std::string{});
        const uint64_t guidArg = args.value("guid", uint64_t{0});
        if (!name.empty())
            target = sCharacterCache->GetCharacterGuidByName(name);
        else if (guidArg != 0)
            target = ObjectGuid::Create<HighGuid::Player>(static_cast<ObjectGuid::LowType>(guidArg));
        else
            return nlohmann::json{{"error", "provide 'name' or 'guid'"}};
        if (target.IsEmpty() || !sCharacterCache->HasCharacterCacheEntry(target))
            return nlohmann::json{{"error", "no such character"}, {"name", name}, {"guid", guidArg}};

        const ObjectGuid::LowType low = target.GetCounter();
        std::string charName;
        sCharacterCache->GetCharacterNameByGuid(target, charName);
        const uint32 accountId = sCharacterCache->GetCharacterAccountIdByGuid(target);
        const uint8  level     = sCharacterCache->GetCharacterLevelByGuid(target);
        std::string accountName;
        AccountMgr::GetName(accountId, accountName);

        nlohmann::json info = {
            {"guid", low}, {"name", charName}, {"level", level},
            {"account_id", accountId}, {"account", accountName}
        };

        // Footgun guards: the admin dispatch master and the Overlord login character are
        // infrastructure, not playmates. Deleting either strands every admin verb.
        if (low == g_McpLeaderSystemMasterGuid || low == g_OverlordCharacterGuid)
        {
            info["error"] = "refusing: this guid is Mcp.Leader.SystemMasterGuid / Overlord.CharacterGuid (admin infrastructure)";
            return info;
        }
        if (ObjectAccessor::FindConnectedPlayer(target))
        {
            info["error"] = "character is online — despawn it first (leader_admin_command 'remove " + charName + "'), then retry";
            info["online"] = true;
            return info;
        }
        info["online"] = false;

        if (args.value("dry_run", false))
        {
            info["dry_run"] = true;
            info["would_delete"] = true;
            return info;
        }
        if (!args.value("confirm", false))
        {
            info["error"] = "pass confirm:true to permanently delete (or dry_run:true to preview)";
            return info;
        }

        LOG_INFO("server.loading",
                 "[Ollama Chat MCP CharDelete] leader={} deleting guid={} name='{}' level={} account={}({})",
                 leaderGuid, low, charName, level, accountId, accountName);
        Player::DeleteFromDB(low, accountId, /*updateRealmChars=*/true, /*deleteFinally=*/true);

        // The proof that matters for a re-roll: the name is free again right now.
        const bool cacheCleared = !sCharacterCache->HasCharacterCacheEntry(target);
        info["ok"] = cacheCleared;
        info["deleted"] = true;
        info["cache_cleared"] = cacheCleared;
        info["name_free_for_reuse"] = cacheCleared;
        if (!cacheCleared)
            info["warning"] = "DeleteFromDB returned but the character cache still holds the entry — a worldserver restart will clear it";
        return info;
    }

    // Server-side character creation through the ENGINE's own path — the same
    // sequence WorldSession::HandleCharCreateOpcode runs for a real client, and the
    // one mod-playerbots' RandomPlayerbotFactory::CreateRandomBot uses to manufacture
    // its whole random population without a client: headless WorldSession ->
    // Player::Create(newGuid, CharacterCreateInfo) -> SaveToDB(create=true) ->
    // sCharacterCache->AddCharacterCacheEntry. This is NOT the "SQL-insert a
    // character" anti-pattern the runbook warns about; every one of the 20+ tables
    // is written by Player::SaveToDB exactly as for a client-created character.
    //
    // Two things the factory skips that the real handler does, done here because the
    // character may be a HUMAN's: AT_LOGIN_FIRST (first-login setup + intro cinematic)
    // and sScriptMgr->OnPlayerCreate (module hooks). Bots get the factory's flags.
    // Appearance is a random VALID combination for the race/gender from
    // sCharSectionsStore (as the factory does); `.character customize` can re-pick it.
    namespace
    {
        uint8 ParseRace(const nlohmann::json& v)
        {
            if (v.is_number_integer()) return static_cast<uint8>(v.get<int>());
            std::string s = v.is_string() ? v.get<std::string>() : std::string{};
            std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
            s.erase(std::remove_if(s.begin(), s.end(), [](unsigned char c){ return c == ' ' || c == '_' || c == '-'; }), s.end());
            static const std::unordered_map<std::string, uint8> m = {
                {"human", RACE_HUMAN}, {"orc", RACE_ORC}, {"dwarf", RACE_DWARF}, {"nightelf", RACE_NIGHTELF},
                {"undead", RACE_UNDEAD_PLAYER}, {"forsaken", RACE_UNDEAD_PLAYER}, {"tauren", RACE_TAUREN},
                {"gnome", RACE_GNOME}, {"troll", RACE_TROLL}, {"bloodelf", RACE_BLOODELF}, {"draenei", RACE_DRAENEI}
            };
            auto it = m.find(s); return it == m.end() ? 0 : it->second;
        }
        uint8 ParseClass(const nlohmann::json& v)
        {
            if (v.is_number_integer()) return static_cast<uint8>(v.get<int>());
            std::string s = v.is_string() ? v.get<std::string>() : std::string{};
            std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
            s.erase(std::remove_if(s.begin(), s.end(), [](unsigned char c){ return c == ' ' || c == '_' || c == '-'; }), s.end());
            static const std::unordered_map<std::string, uint8> m = {
                {"warrior", CLASS_WARRIOR}, {"paladin", CLASS_PALADIN}, {"hunter", CLASS_HUNTER}, {"rogue", CLASS_ROGUE},
                {"priest", CLASS_PRIEST}, {"deathknight", CLASS_DEATH_KNIGHT}, {"dk", CLASS_DEATH_KNIGHT},
                {"shaman", CLASS_SHAMAN}, {"mage", CLASS_MAGE}, {"warlock", CLASS_WARLOCK}, {"druid", CLASS_DRUID}
            };
            auto it = m.find(s); return it == m.end() ? 0 : it->second;
        }
    }

    nlohmann::json Tool_LeaderAdminCreateCharacter(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!g_McpLeaderEnable)
            return nlohmann::json{{"error", "leader mode disabled (set OllamaChat.Mcp.Leader.Enable = 1)"}};
        if (!IsLeaderBot(leaderGuid))
            return nlohmann::json{{"error", "bot not authorized as leader (Mcp.Leader.BotGUIDs)"}};
        if (!g_McpLeaderAllowAdminCommands)
            return nlohmann::json{{"error", "admin commands disabled (set OllamaChat.Mcp.Leader.AllowAdminCommands = 1)"}};
        if (!TryClaimLeaderRateSlot(leaderGuid))
            return nlohmann::json{{"error", "rate-limited"}};

        // ---- arguments ----
        std::string name = args.value("name", std::string{});
        const uint8 race = args.contains("race")  ? ParseRace(args["race"])   : 0;
        const uint8 cls  = args.contains("class") ? ParseClass(args["class"]) : 0;
        std::string genderStr = args.value("gender", std::string{});
        std::transform(genderStr.begin(), genderStr.end(), genderStr.begin(), [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
        const uint8 gender = genderStr == "female" ? GENDER_FEMALE
                           : genderStr == "male"   ? GENDER_MALE
                           : (urand(0, 1) ? GENDER_MALE : GENDER_FEMALE);
        // Account: explicit, else the account that owns the admin dispatch master
        // (Overlord / Botmaster) — i.e. the operator's own account, so the new
        // character shows up on the operator's character screen and can be an alt bot.
        uint32 accountId = args.value("account_id", uint32{0});
        if (accountId == 0 && g_McpLeaderSystemMasterGuid)
            accountId = sCharacterCache->GetCharacterAccountIdByGuid(ObjectGuid::Create<HighGuid::Player>(g_McpLeaderSystemMasterGuid));
        const bool firstLogin = args.value("first_login", true);   // human: intro + AT_LOGIN_FIRST; bot: factory flags

        // ---- validation, mirroring HandleCharCreateOpcode's synchronous checks ----
        if (name.empty() || race == 0 || cls == 0)
            return nlohmann::json{{"error", "need 'name', 'race' (e.g. undead/tauren/orc/troll/bloodelf or id) and 'class' (e.g. rogue/warrior/priest or id)"}};
        if (accountId == 0)
            return nlohmann::json{{"error", "no account: pass 'account_id' (SystemMasterGuid is unset, so there is no default)"}};
        // Same normalisation the client path applies before validating.
        name[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(name[0])));
        for (size_t i = 1; i < name.size(); ++i) name[i] = static_cast<char>(std::tolower(static_cast<unsigned char>(name[i])));
        const uint8 nameRc = ObjectMgr::CheckPlayerName(name, /*create=*/true);
        if (nameRc != CHAR_NAME_SUCCESS)
            return nlohmann::json{{"error", "invalid name (2-12 letters, no digits/spaces, not profane/reserved)"}, {"name", name}, {"code", nameRc}};
        if (sObjectMgr->IsReservedName(name))
            return nlohmann::json{{"error", "name is reserved"}, {"name", name}};
        if (!sCharacterCache->GetCharacterGuidByName(name).IsEmpty())
            return nlohmann::json{{"error", "name already taken (character cache) — delete that character first with leader_admin_delete_character"}, {"name", name}};
        PlayerInfo const* pinfo = sObjectMgr->GetPlayerInfo(race, cls);
        if (!pinfo)
            return nlohmann::json{{"error", "invalid race/class combination for this expansion"}, {"race", race}, {"class", cls}};
        if ((1 << (race - 1)) & sWorld->getIntConfig(CONFIG_CHARACTER_CREATING_DISABLED_RACEMASK))
            return nlohmann::json{{"error", "race disabled by worldserver.conf CharacterCreating.Disabled.RaceMask"}, {"race", race}};
        if ((1 << (cls - 1)) & sWorld->getIntConfig(CONFIG_CHARACTER_CREATING_DISABLED_CLASSMASK))
            return nlohmann::json{{"error", "class disabled by worldserver.conf CharacterCreating.Disabled.ClassMask"}, {"class", cls}};
        if (cls == CLASS_DEATH_KNIGHT)
            return nlohmann::json{{"error", "death knight creation has a level-55 prerequisite and a heroic start — not supported here"}};

        nlohmann::json info = {
            {"name", name}, {"race", race}, {"class", cls},
            {"gender", gender == GENDER_FEMALE ? "female" : "male"},
            {"account_id", accountId}, {"first_login", firstLogin}
        };
        if (args.value("dry_run", false)) { info["dry_run"] = true; info["would_create"] = true; return info; }
        if (!args.value("confirm", false)) { info["error"] = "pass confirm:true to create (or dry_run:true to preview)"; return info; }

        // ---- appearance: a random VALID combination for this race/gender (as the factory) ----
        std::vector<uint8> skins, facialHairs;
        std::vector<std::pair<uint8, uint8>> faces, hairs;
        for (CharSectionsEntry const* cs : sCharSectionsStore)
        {
            if (cs->Race != race || cs->Gender != gender) continue;
            switch (cs->GenType)
            {
                case SECTION_TYPE_SKIN:        skins.push_back(cs->Color); break;
                case SECTION_TYPE_FACE:        faces.emplace_back(cs->Type, cs->Color); break;
                case SECTION_TYPE_FACIAL_HAIR: facialHairs.push_back(cs->Type); break;
                case SECTION_TYPE_HAIR:        hairs.emplace_back(cs->Type, cs->Color); break;
                default: break;
            }
        }
        if (faces.empty() || hairs.empty())
            return nlohmann::json{{"error", "no CharSections rows for this race/gender (DBC not loaded?)"}};
        const auto face = faces[urand(0, faces.size() - 1)];
        const auto hair = hairs[urand(0, hairs.size() - 1)];
        const bool noFacialHair = race == RACE_TAUREN || race == RACE_DRAENEI ||
                                  (gender == GENDER_FEMALE && race != RACE_NIGHTELF && race != RACE_UNDEAD_PLAYER);
        const uint8 facialHair = (noFacialHair || facialHairs.empty()) ? 0 : facialHairs[urand(0, facialHairs.size() - 1)];

        // ---- creation: the engine path, verbatim from the factory + the real handler ----
        std::unique_ptr<CharacterCreateInfo> ci = std::make_unique<CharacterCreateInfo>(
            name, race, cls, gender, /*skin=*/face.second, /*face=*/face.first, hair.first, hair.second, facialHair);
        WorldSession* session = new WorldSession(accountId, "", 0x0, nullptr, SEC_PLAYER, EXPANSION_WRATH_OF_THE_LICH_KING,
                                                 time_t(0), LOCALE_enUS, 0, false, false, 0, /*is_bot=*/true);
        Player* p = new Player(session);
        p->GetMotionMaster()->Initialize();
        const ObjectGuid::LowType newGuid = sObjectMgr->GetGenerator<HighGuid::Player>().Generate();
        if (!p->Create(newGuid, ci.get()))
        {
            p->CleanupsBeforeDelete(); delete p; delete session;
            info["error"] = "Player::Create failed (see worldserver log)";
            return info;
        }
        if (firstLogin)
        {
            // Real-client parity: intro cinematic plays unless the server skips them,
            // and the first-login setup runs on the character's first entry to the world.
            // SkipCinematics is a uint32 (0 = play, 1 = skip when the account already has
            // that race, 2 = always skip) — getBoolConfig on it trips the ConfigValueCache
            // variant ASSERT and takes the worldserver down (measured 2026-09-20).
            // Without an account race history here, treat 1 like the handler's
            // "no same race" case: the intro plays.
            if (sWorld->getIntConfig(CONFIG_SKIP_CINEMATICS) == 2) p->setCinematic(1);
            p->SetAtLoginFlag(AT_LOGIN_FIRST);
        }
        else
        {
            p->setCinematic(2);
            p->SetAtLoginFlag(AT_LOGIN_NONE);
        }
        p->SaveToDB(/*create=*/true, /*logout=*/false);
        sScriptMgr->OnPlayerCreate(p);
        sCharacterCache->AddCharacterCacheEntry(p->GetGUID(), accountId, p->GetName(), p->getGender(), p->getRace(), p->getClass(), p->GetLevel());
        sWorld->UpdateRealmCharCount(accountId);
        const std::string finalName = p->GetName();
        p->CleanupsBeforeDelete(); delete p; delete session;

        LOG_INFO("server.loading",
                 "[Ollama Chat MCP CharCreate] leader={} created guid={} name='{}' race={} class={} gender={} account={} first_login={}",
                 leaderGuid, newGuid, finalName, race, cls, gender, accountId, firstLogin);
        info["ok"] = true; info["created"] = true; info["guid"] = newGuid; info["name"] = finalName;
        info["in_cache"] = sCharacterCache->HasCharacterCacheEntry(ObjectGuid::Create<HighGuid::Player>(newGuid));
        return info;
    }

    // ------------------------------------------------------------------
    // Fleet spawn / despawn / teleport — the three primitives a reroll (or any
    // fleet surgery) needs that `.playerbots bot add|remove` cannot provide.
    //
    // Why a dedicated despawn: the Overlord spawns the fleet through
    // sRandomPlayerbotMgr.AddPlayerBot(guid, 0) (the rndbot path), so the bots are
    // owned by the RandomPlayerbotMgr — NOT by any master's PlayerbotMgr. A
    // `.playerbots bot remove` dispatched from the leader OR the Overlord session
    // therefore looks in the wrong map, prints "not your bot" in-game and still
    // returns ok=true (measured 2026-09-20 twice: leader-master and
    // via_system_master). The primitive that works is the owning holder's
    // LogoutPlayerBot(guid); this tool tries the rndbot holder first and every
    // known master's PlayerbotMgr after it, and reports which one owned the bot.
    // ------------------------------------------------------------------
    namespace
    {
        // Resolve `guids` (ints) + `names` (strings, via the character cache) + `all`
        // (the configured fleet: Overlord.AutoSpawnBots ∪ Gateway.BotGUIDs) into a
        // de-duplicated guid list. Returns an error JSON on a bad name, else null.
        nlohmann::json CollectFleetTargets(const nlohmann::json& args, std::vector<uint32>& out)
        {
            std::set<uint32> seen;
            auto add = [&](uint32 g) { if (g && seen.insert(g).second) out.push_back(g); };
            if (args.contains("guids") && args["guids"].is_array())
                for (const auto& g : args["guids"]) if (g.is_number_integer()) add(g.get<uint32>());
            if (args.contains("names") && args["names"].is_array())
                for (const auto& n : args["names"])
                {
                    if (!n.is_string()) continue;
                    ObjectGuid og = sCharacterCache->GetCharacterGuidByName(n.get<std::string>());
                    if (og.IsEmpty())
                        return nlohmann::json{{"error", "no such character"}, {"name", n.get<std::string>()}};
                    add(og.GetCounter());
                }
            if (args.value("all", false))
            {
                for (uint32 g : g_OverlordAutoSpawnBotList) add(g);
                for (uint64_t g : g_GatewayBotGUIDSet) add(static_cast<uint32>(g));
            }
            return nullptr;
        }

        // Master sessions whose PlayerbotMgr may own a bot: the SystemMaster/Overlord
        // and the leader itself (self-mastered since Fleet.EnsureParty).
        std::vector<Player*> KnownMasterSessions(uint64_t leaderGuid)
        {
            std::vector<Player*> v;
            for (uint32 g : {g_McpLeaderSystemMasterGuid, g_OverlordCharacterGuid, static_cast<uint32>(leaderGuid)})
            {
                if (!g) continue;
                Player* p = ObjectAccessor::FindConnectedPlayer(ObjectGuid::Create<HighGuid::Player>(g));
                if (p && p->IsInWorld() && std::find(v.begin(), v.end(), p) == v.end()) v.push_back(p);
            }
            return v;
        }

        // A bot has no client to ACK a teleport. mod-playerbots ACKs for its bots from
        // PlayerbotHolder::UpdateSessions — EXCEPT selfbots (master == self), where it
        // defers to "the player's client", which a headless self-mastered leader
        // (Fleet.EnsureParty) never has. Measured 2026-09-20: the leader sat "being
        // teleported far" forever — not in world, SaveToDB deferred, every tool
        // answering "player not found". So ACK here for any bot, mirroring
        // PlayerbotAI::HandleTeleportAck verbatim (far: HandleMoveWorldportAck; near:
        // a synthetic MSG_MOVE_TELEPORT_ACK), then clear movement as it does.
        void AckBotTeleport(Player* p, nlohmann::json& out)
        {
            if (!p || !p->GetSession() || !PlayerbotsMgr::instance().GetPlayerbotAI(p))
                return;
            if (p->IsBeingTeleportedFar())
            {
                p->GetSession()->HandleMoveWorldportAck();
                out["acked"] = "worldport";
            }
            else if (p->IsBeingTeleportedNear() && p->IsInWorld())
            {
                Player* mover = p->m_mover ? p->m_mover->ToPlayer() : nullptr;
                if (mover)
                {
                    WorldPacket ack(MSG_MOVE_TELEPORT_ACK, 20);
                    ack << mover->GetPackGUID();
                    ack << uint32(0);   // flags
                    ack << uint32(0);   // time
                    p->GetSession()->HandleMoveTeleportAck(ack);
                    out["acked"] = "near";
                }
            }
            if (p->IsInWorld() && p->GetMotionMaster() && !p->IsInFlight())
            {
                p->GetMotionMaster()->Clear(true);
                p->StopMoving();
            }
            out["in_world_after"] = p->IsInWorld();
            out["map_after"] = p->GetMapId();
        }

        nlohmann::json LeaderAdminGate(uint64_t leaderGuid)
        {
            if (!g_McpLeaderEnable)
                return nlohmann::json{{"error", "leader mode disabled (set OllamaChat.Mcp.Leader.Enable = 1)"}};
            if (!IsLeaderBot(leaderGuid))
                return nlohmann::json{{"error", "bot not authorized as leader (Mcp.Leader.BotGUIDs)"}};
            if (!g_McpLeaderAllowAdminCommands)
                return nlohmann::json{{"error", "admin commands disabled (set OllamaChat.Mcp.Leader.AllowAdminCommands = 1)"}};
            if (!TryClaimLeaderRateSlot(leaderGuid))
                return nlohmann::json{{"error", "rate-limited"}};
            return nullptr;
        }
    }

    nlohmann::json Tool_LeaderAdminDespawn(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (nlohmann::json gate = LeaderAdminGate(leaderGuid); !gate.is_null()) return gate;

        std::vector<uint32> targets;
        if (nlohmann::json err = CollectFleetTargets(args, targets); !err.is_null()) return err;
        if (targets.empty())
            return nlohmann::json{{"error", "need 'guids': [..], 'names': [..] or 'all': true"}};
        const bool dryRun = args.value("dry_run", false);

        nlohmann::json report = nlohmann::json::array();
        uint32 despawned = 0;
        for (uint32 g : targets)
        {
            ObjectGuid og = ObjectGuid::Create<HighGuid::Player>(g);
            std::string name; sCharacterCache->GetCharacterNameByGuid(og, name);
            if (g == g_McpLeaderSystemMasterGuid || g == g_OverlordCharacterGuid)
            {
                report.push_back({{"guid", g}, {"name", name}, {"result", "refused"}, {"why", "SystemMaster/Overlord is the admin dispatch session, not a bot"}});
                continue;
            }
            Player* p = ObjectAccessor::FindConnectedPlayer(og);
            if (!p)
            {
                report.push_back({{"guid", g}, {"name", name}, {"result", "already_offline"}});
                continue;
            }
            std::string owner;
            if (sRandomPlayerbotMgr.GetPlayerBot(og))
            {
                owner = "random_bot_mgr";
                if (!dryRun) sRandomPlayerbotMgr.LogoutPlayerBot(og);
            }
            else
            {
                for (Player* master : KnownMasterSessions(leaderGuid))
                {
                    PlayerbotMgr* mgr = PlayerbotsMgr::instance().GetPlayerbotMgr(master);
                    if (mgr && mgr->GetPlayerBot(og))
                    {
                        owner = "master:" + master->GetName();
                        if (!dryRun) mgr->LogoutPlayerBot(og);
                        break;
                    }
                }
            }
            if (owner.empty())
            {
                report.push_back({{"guid", g}, {"name", name}, {"result", "online_but_not_an_owned_bot"},
                                  {"why", "not in the RandomPlayerbotMgr nor in any known master's PlayerbotMgr — a real player, or a bot of another session"}});
                continue;
            }
            report.push_back({{"guid", g}, {"name", name}, {"result", dryRun ? "would_despawn" : "despawn_dispatched"}, {"owner", owner}});
            if (!dryRun) ++despawned;
        }
        if (!dryRun)
            LOG_INFO("server.loading", "[Ollama Chat MCP Despawn] leader={} despawned={} of {} target(s)", leaderGuid, despawned, targets.size());
        return nlohmann::json{{"ok", true}, {"dry_run", dryRun}, {"targets", report}, {"despawned", despawned},
                              {"note", "logout is asynchronous — the characters row flips online=0 within a few seconds; "
                                       "Overlord.AutoSpawnBots re-spawns them only at the Overlord's own login or via leader_admin_spawn / leader_admin_set_fleet"}};
    }

    nlohmann::json Tool_LeaderAdminSpawn(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (nlohmann::json gate = LeaderAdminGate(leaderGuid); !gate.is_null()) return gate;

        std::vector<uint32> targets;
        if (nlohmann::json err = CollectFleetTargets(args, targets); !err.is_null()) return err;
        if (targets.empty())
            return nlohmann::json{{"error", "need 'guids': [..], 'names': [..] or 'all': true"}};
        const bool dryRun = args.value("dry_run", false);

        nlohmann::json report = nlohmann::json::array();
        uint32 spawned = 0;
        for (uint32 g : targets)
        {
            ObjectGuid og = ObjectGuid::Create<HighGuid::Player>(g);
            if (!sCharacterCache->HasCharacterCacheEntry(og))
            {
                report.push_back({{"guid", g}, {"result", "no_such_character"}});
                continue;
            }
            std::string name; sCharacterCache->GetCharacterNameByGuid(og, name);
            if (g == g_McpLeaderSystemMasterGuid || g == g_OverlordCharacterGuid)
            {
                report.push_back({{"guid", g}, {"name", name}, {"result", "refused"}, {"why", "the Overlord logs itself in (Overlord.Enable), it is not a bot"}});
                continue;
            }
            if (Player* p = ObjectAccessor::FindConnectedPlayer(og); p && p->IsInWorld())
            {
                report.push_back({{"guid", g}, {"name", name}, {"result", "already_in_world"}});
                continue;
            }
            // Same path the Overlord's AutoSpawnBots uses: masterAccountId=0 = rndbot,
            // no same-account / guild / linked-account permission checks.
            if (!dryRun) sRandomPlayerbotMgr.AddPlayerBot(og, /*masterAccountId=*/0);
            report.push_back({{"guid", g}, {"name", name}, {"result", dryRun ? "would_spawn" : "spawn_dispatched"}});
            if (!dryRun) ++spawned;
        }
        if (!dryRun)
            LOG_INFO("server.loading", "[Ollama Chat MCP Spawn] leader={} spawned={} of {} target(s)", leaderGuid, spawned, targets.size());
        return nlohmann::json{{"ok", true}, {"dry_run", dryRun}, {"targets", report}, {"spawned", spawned},
                              {"note", "login is asynchronous — poll get_bot_state / the characters row; Fleet.EnsureParty parties them on its next tick"}};
    }

    // Teleport a character. Online: Player::TeleportTo (the engine's own path, same as
    // `.tele`). Offline: Player::SavePositionInDB, the static helper the core uses for
    // exactly this ("move a character that is not logged in"), so the next login lands
    // at the new spot. Destination is ONE of: explicit {map,x,y,z[,o]}, `to_character`
    // (name or guid; its live position if online, else its saved row), or
    // `to_race_start` (a race's level-1 start, from playercreateinfo — e.g. gather a
    // mixed-race trio at one starting zone). Zone for the offline write is resolved
    // by the map (sMapMgr->GetZoneId), never guessed.
    nlohmann::json Tool_LeaderAdminTeleport(uint64_t leaderGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (nlohmann::json gate = LeaderAdminGate(leaderGuid); !gate.is_null()) return gate;

        // ---- who ----
        ObjectGuid target;
        if (args.contains("guid") && args["guid"].is_number_integer())
            target = ObjectGuid::Create<HighGuid::Player>(args["guid"].get<uint32>());
        else if (args.contains("name") && args["name"].is_string())
            target = sCharacterCache->GetCharacterGuidByName(args["name"].get<std::string>());
        if (target.IsEmpty() || !sCharacterCache->HasCharacterCacheEntry(target))
            return nlohmann::json{{"error", "need 'name' or 'guid' of an existing character"}};
        std::string targetName; sCharacterCache->GetCharacterNameByGuid(target, targetName);
        if (target.GetCounter() == g_McpLeaderSystemMasterGuid || target.GetCounter() == g_OverlordCharacterGuid)
            return nlohmann::json{{"error", "refusing to move the SystemMaster/Overlord session"}};

        // ---- recovery: a bot stuck mid-teleport (see AckBotTeleport) — just ACK it ----
        if (args.value("ack_pending", false))
        {
            Player* stuck = ObjectAccessor::FindConnectedPlayer(target);
            if (!stuck)
                return nlohmann::json{{"error", "target has no session"}, {"name", targetName}};
            if (!stuck->IsBeingTeleported())
                return nlohmann::json{{"ok", true}, {"name", targetName}, {"note", "nothing pending — target is not mid-teleport"}, {"in_world", stuck->IsInWorld()}};
            nlohmann::json r = {{"guid", target.GetCounter()}, {"name", targetName}, {"method", "ack_only"}};
            AckBotTeleport(stuck, r);
            r["ok"] = r.value("in_world_after", false);
            LOG_INFO("server.loading", "[Ollama Chat MCP Teleport] leader={} ack_pending for {} ({}) -> in_world={}",
                     leaderGuid, targetName, target.GetCounter(), r["ok"].get<bool>());
            return r;
        }

        // ---- where ----
        uint32 map = 0; float x = 0, y = 0, z = 0, o = 0; std::string how;
        if (args.contains("to_race_start"))
        {
            const uint8 race = ParseRace(args["to_race_start"]);
            CharacterCacheEntry const* ce = sCharacterCache->GetCharacterCacheByGuid(target);
            const uint8 cls = ce ? ce->Class : CLASS_WARRIOR;
            PlayerInfo const* pinfo = race ? sObjectMgr->GetPlayerInfo(race, cls) : nullptr;
            if (!pinfo && race) pinfo = sObjectMgr->GetPlayerInfo(race, CLASS_WARRIOR);   // start position is per race; any base class will do
            if (!pinfo)
                return nlohmann::json{{"error", "unknown race for to_race_start (human|orc|dwarf|nightelf|undead|tauren|gnome|troll|bloodelf|draenei or id)"}};
            map = pinfo->mapId; x = pinfo->positionX; y = pinfo->positionY; z = pinfo->positionZ; o = pinfo->orientation;
            how = "race_start";
        }
        else if (args.contains("to_character"))
        {
            ObjectGuid ref;
            if (args["to_character"].is_number_integer()) ref = ObjectGuid::Create<HighGuid::Player>(args["to_character"].get<uint32>());
            else if (args["to_character"].is_string())    ref = sCharacterCache->GetCharacterGuidByName(args["to_character"].get<std::string>());
            if (ref.IsEmpty() || !sCharacterCache->HasCharacterCacheEntry(ref))
                return nlohmann::json{{"error", "to_character: no such character"}};
            if (Player* rp = ObjectAccessor::FindConnectedPlayer(ref); rp && rp->IsInWorld())
            {
                map = rp->GetMapId(); x = rp->GetPositionX(); y = rp->GetPositionY(); z = rp->GetPositionZ(); o = rp->GetOrientation();
                how = "character_live";
            }
            else if (QueryResult res = CharacterDatabase.Query("SELECT map, position_x, position_y, position_z, orientation FROM characters WHERE guid = {}", ref.GetCounter()))
            {
                Field* f = res->Fetch();
                map = f[0].Get<uint16>(); x = f[1].Get<float>(); y = f[2].Get<float>(); z = f[3].Get<float>(); o = f[4].Get<float>();
                how = "character_saved_row";
            }
            else return nlohmann::json{{"error", "to_character: no characters row"}};
        }
        else if (args.contains("map") && args.contains("x") && args.contains("y") && args.contains("z"))
        {
            map = args.value("map", uint32{0}); x = args.value("x", 0.0f); y = args.value("y", 0.0f); z = args.value("z", 0.0f); o = args.value("o", 0.0f);
            how = "explicit";
        }
        else
            return nlohmann::json{{"error", "need a destination: to_race_start, to_character, or map+x+y+z[+o]"}};
        if (!sMapStore.LookupEntry(map))
            return nlohmann::json{{"error", "destination map id does not exist"}, {"map", map}};

        Player* p = ObjectAccessor::FindConnectedPlayer(target);
        const bool online = p && p->IsInWorld();
        nlohmann::json plan = {{"guid", target.GetCounter()}, {"name", targetName}, {"online", online},
                               {"destination", {{"how", how}, {"map", map}, {"x", x}, {"y", y}, {"z", z}, {"o", o}}}};
        if (args.value("dry_run", false)) { plan["dry_run"] = true; return plan; }

        std::string method;
        if (online)
        {
            if (p->IsInCombat())
                return nlohmann::json{{"error", "target is in combat"}, {"name", targetName}};
            if (p->IsBeingTeleported())
                return nlohmann::json{{"error", "target is already mid-teleport — pass ack_pending:true to complete it instead"}, {"name", targetName}};
            const bool ok = p->TeleportTo(map, x, y, z, o);
            method = "TeleportTo";
            plan["ok"] = ok;
            if (!ok) plan["error"] = "TeleportTo refused (unreachable map / instance rules)";
            if (ok) AckBotTeleport(p, plan);
        }
        else
        {
            const uint32 zone = sMapMgr->GetZoneId(PHASEMASK_NORMAL, map, x, y, z);
            Player::SavePositionInDB(map, x, y, z, o, zone, target);
            method = "SavePositionInDB";
            plan["ok"] = true; plan["zone"] = zone;
        }
        plan["method"] = method;
        LOG_INFO("server.loading", "[Ollama Chat MCP Teleport] leader={} moved {} ({}) -> map={} ({:.1f},{:.1f},{:.1f}) via {} [{}]",
                 leaderGuid, targetName, target.GetCounter(), map, x, y, z, method, how);
        return plan;
    }

