    nlohmann::json Tool_OpsAuditSummary(uint64_t /*botGuid*/, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        if (!g_OpsEnable)
            return nlohmann::json{{"error", "ops-api tools disabled (OllamaChat.Ops.Enable=0)"}};
        std::vector<std::pair<std::string, std::string>> q;
        if (args.contains("window") && args["window"].is_string())
            q.emplace_back("window", args.value("window", ""));
        return CallOpsApi("/v1/audit/summary", q);
    }

    // ---- Find-by-role landmark queries -------------------------------------
    // Promote the role flags on get_nearby_creatures into first-class tools so the
    // agent can reach for the right one directly ("I need to repair → find_vendor")
    // instead of pulling the entire creature list and filtering. Each tool is a thin
    // wrapper around a shared helper with a role-specific predicate; the response
    // intentionally omits is_vendor/is_trainer/etc. since the role is already
    // implied by the tool name.
    nlohmann::json FindNearbyByRole(uint64_t botGuid, const nlohmann::json& args,
                                    const char* roleName,
                                    const std::function<bool(Creature*)>& pred)
    {
        if (botGuid == 0)
            return nlohmann::json{{"error", "missing required argument 'botGuid' (numeric)"}};
        Player* bot = ObjectAccessor::FindPlayer(ObjectGuid(botGuid));
        if (!bot || !bot->IsInWorld()) return nlohmann::json{{"error", "bot not in world"}};

        // Default radius 60y is wider than get_nearby_creatures (30y) — service NPCs
        // tend to be hub-clustered and the agent typically wants "the nearest one in
        // the city", not "the one in arm's reach". Capped at 500y same as the parent.
        float radius    = static_cast<float>(args.value("radius", 60.0));
        int   limit     = args.value("limit", 10);
        bool  onlyAlive = args.value("only_alive", true);
        if (radius <= 0.0f || radius > 500.0f) radius = 60.0f;
        if (limit <= 0 || limit > 100) limit = 10;

        std::list<Creature*> creatures;
        Acore::AnyUnitInObjectRangeCheck check(bot, radius);
        Acore::CreatureListSearcher<Acore::AnyUnitInObjectRangeCheck> searcher(bot, creatures, check);
        Cell::VisitObjects(bot, searcher, radius);

        std::vector<std::pair<float, Creature*>> scored;
        scored.reserve(creatures.size());
        for (Creature* c : creatures)
        {
            if (!c) continue;
            if (onlyAlive && !c->IsAlive()) continue;
            if (!pred(c)) continue;
            scored.emplace_back(bot->GetDistance(c), c);
        }
        std::sort(scored.begin(), scored.end(),
                  [](auto const& a, auto const& b){ return a.first < b.first; });

        nlohmann::json arr = nlohmann::json::array();
        for (auto const& [dist, c] : scored)
        {
            if (static_cast<int>(arr.size()) >= limit) break;
            nlohmann::json e;
            e["name"]       = c->GetName();
            e["entry"]      = c->GetEntry();
            e["level"]      = c->GetLevel();
            e["distance"]   = static_cast<int>(dist);
            e["is_alive"]   = c->IsAlive();
            e["is_hostile"] = bot->IsHostileTo(c);
            arr.push_back(std::move(e));
        }
        return nlohmann::json{
            {"role",      roleName},
            {"radius",    radius},
            {"matched",   scored.size()},
            {"returned",  arr.size()},
            {"creatures", std::move(arr)}
        };
    }

    nlohmann::json Tool_FindStableMaster(uint64_t botGuid, uint64_t /*playerGuid*/, const nlohmann::json& args)
    {
        // Stable masters have no dedicated Unit::Is* helper (unlike IsTaxi/IsInnkeeper),
        // so match the raw NPC flag directly — the same idiom the auctioneer scans use.
        return FindNearbyByRole(botGuid, args, "stable_master",
            [](Creature* c){ return c->HasNpcFlag(UNIT_NPC_FLAG_STABLEMASTER); });
    }

